/** Sync times shown in Manila time: "Today 9:58 AM", "Yesterday 6:12 PM", "Oct 25, 3:04 PM" (+ year if not this year). */
import type { SyncEntry } from './sync';

export const MANILA = 'Asia/Manila';

function dayKey(ms: number, tz: string): string {
  return new Intl.DateTimeFormat('en-CA', { timeZone: tz, year: 'numeric', month: '2-digit', day: '2-digit' }).format(new Date(ms));
}

export function clockTime(ms: number, tz = MANILA): string {
  return new Intl.DateTimeFormat('en-US', { timeZone: tz, hour: 'numeric', minute: '2-digit' }).format(new Date(ms));
}

export function syncWhen(ms: number, now = Date.now(), tz = MANILA): string {
  const d = dayKey(ms, tz);
  if (d === dayKey(now, tz)) return `Today ${clockTime(ms, tz)}`;
  if (d === dayKey(now - 86400000, tz)) return `Yesterday ${clockTime(ms, tz)}`;
  const sameYear = d.slice(0, 4) === dayKey(now, tz).slice(0, 4);
  const date = new Intl.DateTimeFormat('en-US', { timeZone: tz, month: 'short', day: 'numeric', year: sameYear ? undefined : 'numeric' }).format(new Date(ms));
  return `${date}, ${clockTime(ms, tz)}`;
}

/** "just now", "12 min ago", "3 h ago", "2 days ago". */
export function ago(ms: number, now = Date.now()): string {
  const s = Math.max(0, Math.round((now - ms) / 1000));
  if (s < 60) return 'just now';
  const m = Math.floor(s / 60);
  if (m < 60) return `${m} min ago`;
  const hr = Math.floor(m / 60);
  if (hr < 48) return `${hr} h ago`;
  return `${Math.floor(hr / 24)} days ago`;
}

/** The Sync box lines: last successful sync, a newer failed try, and what's waiting. */
export function syncLines(st: { lastSyncAt: number | null; lastFailAt: number | null; lastError: string | null; pending: number; failed: number; state: string },
  now = Date.now(), tz = MANILA): string[] {
  const out = [st.lastSyncAt ? `Last sync: ${syncWhen(st.lastSyncAt, now, tz)} (${ago(st.lastSyncAt, now)})` : 'Last sync: none recorded on this device yet'];
  if (st.lastFailAt && (!st.lastSyncAt || st.lastFailAt > st.lastSyncAt)) {
    out.push(`Last try failed ${syncWhen(st.lastFailAt, now, tz)}${st.lastError ? ': ' + st.lastError : ''}`);
  }
  if (st.pending) out.push(`${st.pending} change${st.pending === 1 ? '' : 's'} waiting to sync`);
  if (st.failed) out.push(`${st.failed} refused by the sheet (see below)`);
  return out;
}

/** One log row: "Today 9:58 AM · ✓ sent 3 · got the sheet (85 items) · 1.2 s". */
export function logLine(e: SyncEntry, now = Date.now(), tz = MANILA): string {
  const parts = [syncWhen(e.at, now, tz), e.ok ? '✓' : '✗ failed'];
  if (e.sent) parts.push(`sent ${e.sent}`);
  if (e.refused) parts.push(`${e.refused} refused`);
  if (e.got) parts.push(`got the sheet${e.items !== undefined ? ` (${e.items} items)` : ''}`);
  if (!e.sent && !e.refused && !e.got && e.ok) parts.push('nothing to do');
  parts.push(`${(e.ms / 1000).toFixed(1)} s`);
  if (!e.ok && e.error) parts.push(e.error);
  return parts.join(' · ');
}
