/**
 * Camera barcode scanner.
 * - One camera stream per scan session: paused while a form is open, never
 *   restarted per scan (fewer camera prompts, notably on iPhone home-screen apps).
 * - Decoding: the browser's own BarcodeDetector whenever it exists and works
 *   (Chrome on Android: Google Play services), otherwise ZXing-C++ compiled to
 *   WebAssembly via the `barcode-detector` ponyfill. The .wasm file is bundled
 *   with the app (not fetched from a CDN), so scanning works offline.
 * - Speed: detection runs back to back on new camera frames
 *   (requestVideoFrameCallback, else requestAnimationFrame), one at a time.
 *   ZXing decodes only the centre band around the aim line, scaled down.
 * - Camera: asks for 1080p, continuous focus and a small zoom when offered.
 */
import wasmUrl from 'zxing-wasm/reader/zxing_reader.wasm?url';
import { cornersOf, type DetectedBarcode, type Point } from './core/scanFeedback';
import { cameraTweaks, centerCrop, uncrop, DetectStats, type CameraCaps, type ScannerInfo } from './core/camera';

type Detector = { detect(source: CanvasImageSource): Promise<(DetectedBarcode & { format?: string })[]> };
type Engine = { detector: Detector; engine: 'native' | 'zxing'; reason?: string };

export interface ScannerEvents {
  /** A barcode came into view (once per appearance). corners are in video pixels, or null. */
  onCode(code: string, corners: Point[] | null): void;
  /** Any frame where a barcode was read, including one still in view (feeds the can't-read hint). */
  onRead?(): void;
}

const FORMATS = ['ean_13', 'ean_8', 'upc_a', 'upc_e', 'code_128', 'code_39', 'itf'];
/** Native detect() errors in a row before switching to ZXing (one empty frame is not an error). */
const NATIVE_FAILS_BEFORE_FALLBACK = 3;

let enginePromise: Promise<Engine> | null = null;

async function nativeEngine(): Promise<Engine | string> {
  const Native = (globalThis as any).BarcodeDetector;
  if (!Native) return 'this browser has no built-in barcode scanner';
  // Ask only for our formats when the browser lists them; if it lists none
  // (seen when Play services' scanner isn't ready), ask for all and filter results.
  let formats: string[] = [];
  try {
    const supported: string[] = (await Native.getSupportedFormats?.()) ?? [];
    formats = FORMATS.filter((f) => supported.includes(f));
  } catch { /* keep [] */ }
  let det: Detector;
  try { det = formats.length ? new Native({ formats }) : new Native(); }
  catch (e) { return 'built-in scanner could not start (' + errName(e) + ')'; }
  // A tiny blank frame: throws NotSupportedError when the built-in scanner is unavailable.
  try {
    const probe = document.createElement('canvas'); probe.width = probe.height = 16;
    await det.detect(probe);
  } catch (e) { return 'built-in scanner failed (' + errName(e) + ')'; }
  return { detector: det, engine: 'native' };
}

async function zxingEngine(reason: string): Promise<Engine> {
  const mod = await import('barcode-detector/ponyfill');
  mod.prepareZXingModule({
    overrides: { locateFile: (path: string, prefix: string) => (path.endsWith('.wasm') ? wasmUrl : prefix + path) },
  });
  return { detector: new mod.BarcodeDetector({ formats: FORMATS as any }) as unknown as Detector, engine: 'zxing', reason };
}

export function getDetector(): Promise<Engine> {
  enginePromise ??= nativeEngine().then((r) => (typeof r === 'string' ? zxingEngine(r) : r));
  return enginePromise;
}

function errName(e: unknown) { return (e as Error)?.name || String(e); }

export function cameraAvailable(): boolean {
  return !!navigator.mediaDevices?.getUserMedia;
}

async function openCamera(): Promise<MediaStream> {
  const video = (width: number, height: number) => ({ facingMode: { ideal: 'environment' }, width: { ideal: width }, height: { ideal: height } });
  try { return await navigator.mediaDevices.getUserMedia({ audio: false, video: video(1920, 1080) }); }
  catch (e) {
    if (errName(e) !== 'OverconstrainedError') throw e;
    return navigator.mediaDevices.getUserMedia({ audio: false, video: video(1280, 720) });
  }
}

export class CameraScanner {
  private stream: MediaStream | null = null;
  private track: MediaStreamTrack | null = null;
  private engine: Engine | null = null;
  private paused = false;
  private generation = 0;           // bumps on stop() so a late frame callback does nothing
  private frameHandle: number | null = null;
  private usingVfc = false;
  private lastCode = '';
  private lastAt = 0;
  private nativeFails = 0;
  private canvas: HTMLCanvasElement | null = null;
  private ctx: CanvasRenderingContext2D | null = null;
  private stats = new DetectStats();
  torchSupported = false;
  torchOn = false;

  constructor(private video: HTMLVideoElement, private events: ScannerEvents) {}

  get running() { return !!this.stream; }

  async start(): Promise<void> {
    if (this.stream) { this.resume(); return; }
    this.engine = await getDetector();
    this.stream = await openCamera();
    this.track = this.stream.getVideoTracks()[0] ?? null;
    await this.tuneCamera();
    this.video.srcObject = this.stream;
    this.video.setAttribute('playsinline', '');
    this.video.muted = true;
    await this.video.play();
    this.paused = false;
    this.schedule(++this.generation);
  }

  /** Continuous focus and a little zoom when the camera offers them; each one optional. */
  private async tuneCamera() {
    const t = this.track as any;
    let caps: CameraCaps | null = null;
    try { caps = t?.getCapabilities?.() ?? null; } catch { /* not supported */ }
    const want = cameraTweaks(caps);
    for (const [k, v] of Object.entries(want)) {
      try { await t.applyConstraints({ advanced: [{ [k]: v }] }); } catch { /* camera refused this one */ }
    }
    this.torchSupported = caps?.torch === true;
  }

  async setTorch(on: boolean): Promise<boolean> {
    if (!this.track || !this.torchSupported) return false;
    try { await this.track.applyConstraints({ advanced: [{ torch: on } as any] }); this.torchOn = on; }
    catch { /* keep the old state */ }
    return this.torchOn;
  }

  /** What the device is actually using, for the "This device" section. */
  info(): ScannerInfo | null {
    if (!this.engine) return null;
    let s: any = {};
    try { s = this.track?.getSettings?.() ?? {}; } catch { /* ignore */ }
    return {
      engine: this.engine.engine, reason: this.engine.reason,
      width: s.width || this.video.videoWidth || undefined, height: s.height || this.video.videoHeight || undefined,
      focusMode: s.focusMode, zoom: typeof s.zoom === 'number' ? Math.round(s.zoom * 100) / 100 : undefined,
      torch: this.torchSupported, avgDetectMs: this.stats.avg, detects: this.stats.count, at: Date.now(),
    };
  }

  private schedule(gen: number) {
    if (gen !== this.generation || !this.stream) return;
    const v = this.video as HTMLVideoElement & { requestVideoFrameCallback?: (cb: () => void) => number };
    this.usingVfc = typeof v.requestVideoFrameCallback === 'function';
    const next = () => this.tick(gen);
    this.frameHandle = this.usingVfc ? v.requestVideoFrameCallback!(next) : requestAnimationFrame(next);
  }

  /** One frame: decode it if we're scanning, then wait for the next frame. Never two at once. */
  private async tick(gen: number) {
    if (gen !== this.generation) return;
    if (!this.paused && this.video.readyState >= 2) await this.detectOnce();
    this.schedule(gen);
  }

  private async detectOnce() {
    const eng = this.engine!;
    const t0 = performance.now();
    let found: (DetectedBarcode & { format?: string })[] = [];
    let crop = null;
    try {
      if (eng.engine === 'native') {
        found = await eng.detector.detect(this.video);
        this.nativeFails = 0;
      } else {
        crop = this.drawCrop();
        if (!crop) return;
        found = await eng.detector.detect(this.canvas!);
      }
    } catch (e) {
      if (eng.engine === 'native' && ++this.nativeFails >= NATIVE_FAILS_BEFORE_FALLBACK) {
        enginePromise = zxingEngine('built-in scanner stopped working (' + errName(e) + ')');
        this.engine = await enginePromise;
      }
      return; // with ZXing, a frame that fails to decode is normal
    } finally {
      this.stats.add(performance.now() - t0);
    }
    const hit = found.find((b) => b.rawValue?.trim() && (!b.format || b.format === 'unknown' || FORMATS.includes(b.format)));
    const code = hit?.rawValue.trim();
    if (!hit || !code) return;
    this.events.onRead?.();
    const now = Date.now();
    // Fire once per appearance: the same barcode fires again only after it
    // has been out of view for a moment (so a code still in frame after
    // Save does not reopen the form).
    const fresh = code !== this.lastCode || now - this.lastAt > 1500;
    this.lastCode = code; this.lastAt = now;
    if (!fresh) return;
    const corners = cornersOf(hit);
    this.events.onCode(code, corners && crop ? uncrop(corners, crop) : corners);
  }

  /** Draws the centre band of the frame onto a reused, scaled-down canvas (ZXing only). */
  private drawCrop() {
    const v = this.video;
    const crop = centerCrop({ width: v.videoWidth, height: v.videoHeight }, { width: v.clientWidth, height: v.clientHeight });
    if (!crop) return null;
    this.canvas ??= document.createElement('canvas');
    this.ctx ??= this.canvas.getContext('2d', { willReadFrequently: true });
    if (!this.ctx) return null;
    const w = Math.round(crop.width * crop.scale), h = Math.round(crop.height * crop.scale);
    if (this.canvas.width !== w) this.canvas.width = w;
    if (this.canvas.height !== h) this.canvas.height = h;
    this.ctx.drawImage(v, crop.x, crop.y, crop.width, crop.height, 0, 0, w, h);
    return crop;
  }

  /** Keep the stream (and permission) but stop decoding, e.g. while a form is open. */
  pause() { this.paused = true; }

  resume() {
    this.paused = false;
    this.lastAt = Date.now(); // the last code must leave view before it fires again
    if (this.video.paused) this.video.play().catch(() => {});
  }

  /** Release the camera completely (leaving the scanner, or app in background). */
  stop() {
    this.generation++;
    if (this.frameHandle !== null) {
      const v = this.video as any;
      if (this.usingVfc) v.cancelVideoFrameCallback?.(this.frameHandle); else cancelAnimationFrame(this.frameHandle);
    }
    this.frameHandle = null;
    this.stream?.getTracks().forEach((t) => t.stop());
    this.stream = null;
    this.track = null;
    this.torchOn = false;
    this.video.srcObject = null;
  }
}

export function cameraErrorMessage(e: unknown): string {
  const name = (e as DOMException)?.name;
  if (name === 'NotAllowedError') return 'Camera permission was refused. Allow the camera for this app in the browser settings, or type / use a USB scanner below.';
  if (name === 'NotFoundError' || name === 'OverconstrainedError') return 'No camera found. Type the barcode or use a USB scanner below.';
  if (name === 'NotReadableError') return 'The camera is busy in another app. Close it and tap Start camera.';
  return 'Could not start the camera (' + (name || String(e)) + '). Type the barcode or use a USB scanner below.';
}
