/**
 * Pick-or-type box (ARIA combobox with a list). Built by hand because a
 * <datalist> on Android Chrome only shows suggestions as you type, can't show
 * the whole list on tap, and can't be styled for touch.
 *
 * - Tap the box: the whole list opens under it (A–Z); tap a choice and you're done.
 * - Type: the list narrows; Enter / Next keeps what you typed (using the
 *   list's spelling if it matches one) and moves to the next field.
 * - Something new: a "Use “…” (new)" row under any matches, or just Enter.
 */
import { h } from '../dom';
import { canonicalChoice, filterChoices, isNewChoice } from '../core/choices';

export interface ComboOptions {
  label: string;
  value?: string;
  /** Called each time the list opens, so it includes anything added since. */
  options: () => string[];
  placeholder?: string;
  maxLength?: number;
  autocapitalize?: 'off' | 'words' | 'sentences';
  autofocus?: boolean;
  /** After a pick, Enter, or leaving the box, with the saved spelling. */
  onCommit?: (value: string) => void;
  /** A muted second line under a choice (e.g. a store's area). */
  describe?: (value: string) => string;
  /** Text of the row offering what was typed (default: Use “…” (new)). */
  newLabel?: (typed: string) => string;
  /** When set, picking the "new" row (or Enter on new text) calls this instead of keeping the text. */
  onNew?: (typed: string) => void;
  /** Custom matching and order for typed text (default: start of a word first, then anywhere). */
  filter?: (options: string[], typed: string) => string[];
}

let seq = 0;

export function combo(o: ComboOptions) {
  const id = 'combo' + ++seq;
  const input = h('input', {
    type: 'text', role: 'combobox', autocomplete: 'off', autocapitalize: o.autocapitalize ?? 'off', spellcheck: 'false',
    enterkeyhint: 'next', 'aria-label': o.label, 'aria-autocomplete': 'list', 'aria-expanded': 'false', 'aria-controls': id,
    placeholder: o.placeholder, maxlength: o.maxLength, value: o.value ?? '', 'data-autofocus': o.autofocus ? 'always' : undefined,
  });
  const list = h('ul', { id, class: 'combo-list', role: 'listbox', 'aria-label': o.label, hidden: true });
  const el = h('div', { class: 'combo' }, input, list);
  let shown: { value: string; isNew: boolean }[] = [];
  let active = -1;
  let opts: string[] = [];

  const optId = (i: number) => `${id}-o${i}`;

  function paint() {
    const typed = input.value;
    // Showing a value that came pre-filled (or was just picked): list everything.
    const matches = opts.some((x) => x === typed) ? [...opts] : (o.filter ?? filterChoices)(opts, typed);
    shown = matches.map((value) => ({ value, isNew: false }));
    // Typed something not on the list: offer it as new, after any partial matches.
    if (isNewChoice(opts, typed)) shown.push({ value: canonicalChoice(opts, typed), isNew: true });
    if (active >= shown.length) active = shown.length - 1;
    list.replaceChildren(...shown.map((s, i) => h('li', {
      id: optId(i), role: 'option', class: 'combo-opt' + (s.isNew ? ' new' : ''),
      'aria-selected': String(i === active || (!s.isNew && s.value === typed)),
      // pointerdown keeps focus in the box (no keyboard flicker); click picks.
      onpointerdown: (e: Event) => e.preventDefault(),
      onclick: () => (s.isNew && o.onNew ? pickNew(s.value) : pick(s.value)),
    }, s.isNew ? (o.newLabel ? o.newLabel(s.value) : `Use “${s.value}” (new)`) : s.value,
    !s.isNew && o.describe?.(s.value) ? h('span', { class: 'combo-hint' }, o.describe(s.value)) : null)));
    list.hidden = shown.length === 0;
    input.setAttribute('aria-expanded', String(!list.hidden));
    if (active >= 0) { input.setAttribute('aria-activedescendant', optId(active)); list.children[active]?.scrollIntoView({ block: 'nearest' }); }
    else input.removeAttribute('aria-activedescendant');
  }

  function open() {
    opts = o.options();
    active = -1;
    paint();
    // Keep the list on screen above the phone keyboard.
    requestAnimationFrame(() => el.scrollIntoView({ block: 'start', behavior: 'smooth' }));
  }

  function close() {
    list.hidden = true;
    input.setAttribute('aria-expanded', 'false');
    input.removeAttribute('aria-activedescendant');
    active = -1;
  }

  function commit() {
    const v = canonicalChoice(opts.length ? opts : o.options(), input.value);
    if (input.value !== v) input.value = v;
    o.onCommit?.(v);
    return v;
  }

  function pick(v: string) {
    input.value = v;
    close();
    commit();
    input.blur(); // done with this box: hides the keyboard so the form is visible
  }

  function pickNew(v: string) {
    close();
    input.blur();
    o.onNew!(v);
  }

  input.addEventListener('focus', () => { open(); input.select(); });
  input.addEventListener('input', () => { active = -1; paint(); });
  input.addEventListener('blur', () => { close(); commit(); });
  input.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowDown' || e.key === 'ArrowUp') {
      e.preventDefault();
      if (list.hidden) open();
      if (!shown.length) return;
      active = e.key === 'ArrowDown' ? (active + 1) % shown.length : (active <= 0 ? shown.length - 1 : active - 1);
      paint();
    } else if (e.key === 'Escape') {
      if (!list.hidden) { e.preventDefault(); close(); }
    } else if (e.key === 'Enter') {
      e.preventDefault();
      if (active >= 0 && shown[active]) input.value = shown[active].value;
      if (o.onNew && isNewChoice(opts.length ? opts : o.options(), input.value)) { pickNew(canonicalChoice(opts, input.value)); return; }
      close();
      commit();
      focusNext(input);
    }
  });

  return {
    el, input,
    get value() { return canonicalChoice(o.options(), input.value); },
    set value(v: string) { input.value = v; },
  };
}

/**
 * The box with its caption. Not a <label>: a tap on a list choice inside a
 * label would re-focus the box and reopen the list.
 */
export function comboField(caption: string | Node, c: { el: HTMLElement; input: HTMLInputElement }) {
  return h('div', { class: 'field' }, h('span', { class: 'field-label', onclick: () => c.input.focus() }, caption), c.el);
}

/** Moves to the next field in the screen, like the keyboard's Next key. */
export function focusNext(from: HTMLElement) {
  const scope = from.closest('main') ?? document.body;
  const fields = [...scope.querySelectorAll<HTMLElement>('input, select, textarea, button')]
    .filter((x) => !x.hasAttribute('disabled') && x.offsetParent !== null && x.tabIndex >= 0);
  const next = fields[fields.indexOf(from) + 1];
  if (next) next.focus(); else from.blur();
}
