import { ApiError, type Api } from './api';
import type { Snapshot } from './types';
import type { WriteQueue } from './queue';

export interface SyncStatus {
  state: 'idle' | 'syncing' | 'offline' | 'error';
  pending: number;
  failed: number;
  /** Last sync that finished without an error (kept on the device across restarts and updates). */
  lastSyncAt: number | null;
  lastError: string | null;
  /** When the last failed try was (only meaningful when newer than lastSyncAt). */
  lastFailAt: number | null;
  /** The last attempts, newest first (at most SYNC_LOG_MAX). */
  log: SyncEntry[];
}

/** One sync attempt. */
export interface SyncEntry {
  at: number;
  ok: boolean;
  /** Saves the sheet accepted / refused in this attempt. */
  sent: number;
  refused: number;
  /** A fresh copy of the sheet was downloaded (and how many items it had). */
  got: boolean;
  items?: number;
  ms: number;
  error?: string;
}

/** What is kept on the device between runs (IndexedDB key "syncLog"). */
export interface SyncHistory { lastOkAt: number | null; lastFailAt: number | null; lastError: string | null; log: SyncEntry[] }

export const SYNC_LOG_MAX = 20;

export interface SyncDeps {
  queue: WriteQueue;
  api: () => Api | null;
  saveSnapshot: (s: Snapshot) => Promise<void>;
  isOnline?: () => boolean;
  now?: () => number;
  /** Device storage for the last sync time and the log (none in tests that don't care). */
  loadHistory?: () => Promise<SyncHistory | undefined>;
  saveHistory?: (h: SyncHistory) => Promise<void>;
}

/**
 * Background sync: sends queued saves in batches and refreshes the cached
 * copy of the sheet. Runs on a timer while the app is open, when the device
 * comes back online, and on "Sync now". Network failures back off and retry;
 * nothing is lost because the queue is on the device.
 */
export class SyncEngine {
  status: SyncStatus = { state: 'idle', pending: 0, failed: 0, lastSyncAt: null, lastError: null, lastFailAt: null, log: [] };
  private running: Promise<void> | null = null;
  private nextTryAt = 0;
  private backoffMs = 0;
  private lastSnapshotAt = 0;
  private listeners = new Set<(s: SyncStatus) => void>();
  readonly snapshotMaxAgeMs = 5 * 60 * 1000;

  constructor(private d: SyncDeps) {
    d.queue.onChange(() => this.emit());
  }

  /** Loads the last sync time and the log saved on this device (call once at start). */
  async init() {
    const h = await this.d.loadHistory?.().catch(() => undefined);
    if (h) this.emit({ lastSyncAt: h.lastOkAt ?? null, lastFailAt: h.lastFailAt ?? null, lastError: h.lastError ?? null, log: Array.isArray(h.log) ? h.log.slice(0, SYNC_LOG_MAX) : [] });
  }

  private async record(e: SyncEntry, patch: Partial<SyncStatus>) {
    const log = [e, ...this.status.log].slice(0, SYNC_LOG_MAX);
    this.emit({ ...patch, log });
    const s = this.status;
    await this.d.saveHistory?.({ lastOkAt: s.lastSyncAt, lastFailAt: s.lastFailAt, lastError: s.lastError, log }).catch(() => undefined);
  }

  onStatus(fn: (s: SyncStatus) => void) { this.listeners.add(fn); return () => this.listeners.delete(fn); }

  private emit(patch: Partial<SyncStatus> = {}) {
    this.status = { ...this.status, ...patch, pending: this.d.queue.pendingCount(), failed: this.d.queue.failed().length };
    this.listeners.forEach((fn) => fn(this.status));
  }

  private now() { return (this.d.now ?? Date.now)(); }
  private online() { return (this.d.isOnline ?? (() => navigator.onLine))(); }

  /** Called by the timer: does work only when there is something to do and backoff allows. */
  tick(): Promise<void> {
    if (this.now() < this.nextTryAt) return Promise.resolve();
    const needSnapshot = this.now() - this.lastSnapshotAt > this.snapshotMaxAgeMs;
    if (this.d.queue.pendingCount() === 0 && !needSnapshot) return Promise.resolve();
    return this.run(needSnapshot);
  }

  /** "Sync now": ignores backoff, always refreshes the sheet copy. */
  syncNow(): Promise<void> {
    this.nextTryAt = 0;
    return this.run(true);
  }

  private run(refresh: boolean): Promise<void> {
    if (this.running) return this.running;
    this.running = this.doRun(refresh).finally(() => { this.running = null; });
    return this.running;
  }

  private async doRun(refresh: boolean) {
    const api = this.d.api();
    if (!api) return;
    if (!this.online()) { this.emit({ state: 'offline' }); return; }
    this.emit({ state: 'syncing' });
    let sent = false;
    const start = this.now();
    let okCount = 0, refused = 0, got = false, items: number | undefined;
    try {
      for (let guard = 0; guard < 20; guard++) {
        const batch = this.d.queue.takeBatch(50);
        if (!batch.length) break;
        try {
          const results = await api.apply(batch);
          await this.d.queue.settle(results);
          results.forEach((r) => { if (r.ok) okCount++; else refused++; });
          sent = true;
        } catch (e) {
          await this.d.queue.retryLater(batch.map((o) => o.opId), (e as Error).message);
          throw e;
        }
      }
      if (refresh || sent) {
        const snap = await api.snapshot();
        await this.d.saveSnapshot(snap);
        this.lastSnapshotAt = this.now();
        got = true;
        items = Array.isArray(snap?.items) ? snap.items.length : undefined;
      }
      this.backoffMs = 0;
      this.nextTryAt = 0;
      const at = this.now();
      await this.record({ at, ok: true, sent: okCount, refused, got, items, ms: at - start }, { state: 'idle', lastSyncAt: at, lastError: null, lastFailAt: null });
    } catch (e) {
      const err = e as ApiError;
      this.backoffMs = Math.min(60000, this.backoffMs ? this.backoffMs * 2 : 5000);
      const at = this.now();
      this.nextTryAt = at + this.backoffMs;
      await this.record({ at, ok: false, sent: okCount, refused, got, items, ms: at - start, error: err.message },
        { state: err.code === 'network' && !this.online() ? 'offline' : 'error', lastError: err.message, lastFailAt: at });
    }
  }
}
