/**
 * Grocery lists (Lists + ListItems tabs): per-line estimates and badges,
 * per-store totals with travel cost, and the split recommendation.
 * Same idea as the sheet's ListItemsCalc / TripSummary, plus product-level
 * comparison and trip areas (stores in one BranchArea add no travel).
 */
import type { GroceryList, Item, ListLine, Op } from './types';
import type { View } from './model';
import { newId } from './ids';
import { areaOf, buildPools, metric, minBy, packSaving, round2, stdQty, usesPerUnit, type Group, type Pools, type PricePoint } from './compare';

export interface Cheaper {
  point: PricePoint;
  /** The pack to buy there (may be another pack of the same product). */
  item: Item;
  perUnit: boolean;
  /** Per unit (or per pack) difference. */
  diff: number;
  /** ₱ saved on this line's quantity. */
  saveLine: number;
  /** Packs of `item` that match this line's amount. */
  qty: number;
}

export interface LineInfo {
  line: ListLine;
  item: Item | undefined;
  group: Group | undefined;
  /** Where this line will be bought: BuyAt, else the list's store. */
  storeId: string;
  /** This item's price at that store, if known. */
  point?: PricePoint;
  /** qty x pack price, or null without a price. */
  cost: number | null;
  /** Cheapest usable price at another store, when lower. */
  cheaper?: Cheaper;
  /** Another pack of the same product at the same store that is cheaper per unit (or the only one priced there). */
  cheaperPack?: { item: Item; point: PricePoint; diff: number };
  /** No price at the buy store: best price known elsewhere (to show). */
  bestKnown?: PricePoint;
}

export function effectiveStore(list: GroceryList, line: ListLine): string { return line.buyAt || list.storeId; }

function pointAt(pools: Pools, g: Group, itemId: string, storeId: string, usable: boolean): PricePoint | undefined {
  return (usable ? pools.badge : pools.display).get(g.key)?.find((p) => p.itemId === itemId && p.storeId === storeId);
}

export function lineInfo(view: View, list: GroceryList, line: ListLine, today: string, pools = buildPools(view, today)): LineInfo {
  const item = view.itemById.get(line.itemId);
  const storeId = effectiveStore(list, line);
  const g = item ? pools.groupOfItem.get(item.id) : undefined;
  const info: LineInfo = { line, item, group: g, storeId, cost: null };
  if (!item || !g) return info;
  const shown = pointAt(pools, g, item.id, storeId, false);
  info.point = shown;
  if (shown) info.cost = round2(shown.price * line.qty);
  const usable = pools.badge.get(g.key) ?? [];
  const here = pointAt(pools, g, item.id, storeId, true) ?? shown;

  // Another pack of the same product at the same store.
  if (g.isProduct) {
    const packs = usable.filter((p) => p.storeId === storeId && p.itemId !== item.id);
    const best = minBy(packs, true);
    if (best && (!here || (here.perStd !== null && best.perStd! < here.perStd - 1e-9))) {
      const other = view.itemById.get(best.itemId);
      if (other) info.cheaperPack = { item: other, point: best, diff: here?.perStd != null ? round2(here.perStd - best.perStd!) : 0 };
    }
  }
  if (!here) {
    info.bestKnown = minBy((pools.display.get(g.key) ?? []).filter((p) => p.itemId === item.id || g.isProduct), usesPerUnit(g, pools.display.get(g.key) ?? []));
    return info;
  }
  const others = usable.filter((p) => p.storeId !== storeId);
  const perUnit = usesPerUnit(g, [here, ...others]);
  const best = minBy(others, perUnit);
  if (best && metric(best, perUnit) < metric(here, perUnit) - 0.005) {
    const d = metric(here, perUnit) - metric(best, perUnit);
    const buy = view.itemById.get(best.itemId) ?? item;
    let qty = line.qty;
    if (buy.id !== item.id) {
      const a = stdQty(item), b = stdQty(buy);
      qty = a && b ? Math.max(1, Math.round((line.qty * a) / b)) : line.qty;
    }
    info.cheaper = { point: best, item: buy, perUnit, diff: round2(d), saveLine: round2(packSaving(here, d, perUnit) * line.qty), qty };
  }
  return info;
}

/* ---------------------------------------------------------------- totals and travel */

export interface StoreTotal { storeId: string; total: number; lines: number; missing: number; approx: boolean }

export interface TripPlan {
  primary: string;
  byStore: StoreTotal[];
  /** Everything as planned (lines without a price left out). */
  total: number;
  missing: number;
  /** Travel for stores outside the list store's area (one fare per area). */
  extraTravel: number;
  extraAreas: string[];
  /** Moved lines: cost at the list's store minus cost where they are planned (both priced). */
  movedSavings: number;
  movedCount: number;
  /** Best single other trip area to move the "cheaper at" lines to (not kept, not already moved). */
  suggestion?: { area: string; storeIds: string[]; lines: number; savings: number; travel: number; net: number };
  splitThreshold: number;
  recommendation: string;
}

/** Round-trip travel for an area: the highest TranspoCostRoundTrip among the given stores in it (blank = 0). */
export function areaTravel(view: View, storeIds: readonly string[]): number {
  return Math.max(0, ...storeIds.map((id) => { const t = view.stores.find((s) => s.id === id)?.transpo; return typeof t === 'number' ? t : 0; }));
}

export function tripPlan(view: View, list: GroceryList, infos: readonly LineInfo[], today: string, pools = buildPools(view, today)): TripPlan {
  const store = (id: string) => view.stores.find((s) => s.id === id);
  const area = (id: string) => areaOf(store(id), id);
  const primaryArea = area(list.storeId);
  const byStore = new Map<string, StoreTotal>();
  for (const i of infos) {
    const t = byStore.get(i.storeId) ?? { storeId: i.storeId, total: 0, lines: 0, missing: 0, approx: false };
    t.lines++;
    if (i.cost === null) t.missing++; else t.total = round2(t.total + i.cost);
    if (i.point && (i.point.approx || i.point.age === 'old')) t.approx = true;
    byStore.set(i.storeId, t);
  }
  const used = new Map<string, string[]>();
  for (const id of byStore.keys()) if (area(id) !== primaryArea) { const a = area(id); used.set(a, [...(used.get(a) ?? []), id]); }
  const extraTravel = [...used.values()].reduce((s, ids) => s + areaTravel(view, ids), 0);

  let movedSavings = 0, movedCount = 0;
  for (const i of infos) {
    if (!i.item || i.storeId === list.storeId) continue;
    movedCount++;
    const g = i.group;
    const atPrimary = g && (pools.display.get(g.key) ?? []).find((p) => p.itemId === i.item!.id && p.storeId === list.storeId);
    if (atPrimary && i.cost !== null) movedSavings += atPrimary.price * i.line.qty - i.cost;
  }
  movedSavings = round2(movedSavings);

  const cand = new Map<string, { storeIds: Set<string>; lines: number; savings: number }>();
  for (const i of infos) {
    if (!i.cheaper || i.line.keep || i.storeId !== list.storeId) continue;
    const a = area(i.cheaper.point.storeId);
    const c = cand.get(a) ?? { storeIds: new Set<string>(), lines: 0, savings: 0 };
    c.storeIds.add(i.cheaper.point.storeId); c.lines++; c.savings = round2(c.savings + i.cheaper.saveLine);
    cand.set(a, c);
  }
  let suggestion: TripPlan['suggestion'];
  for (const [a, c] of cand) {
    const ids = [...c.storeIds];
    const travel = a === primaryArea || used.has(a) ? 0 : areaTravel(view, ids);
    const s = { area: a, storeIds: ids, lines: c.lines, savings: c.savings, travel, net: round2(c.savings - travel) };
    if (!suggestion || s.net > suggestion.net) suggestion = s;
  }

  const threshold = view.settings.splitThreshold;
  const totals = [...byStore.values()].sort((a, b) => (a.storeId === list.storeId ? -1 : b.storeId === list.storeId ? 1 : b.total - a.total));
  const total = round2(totals.reduce((s, t) => s + t.total, 0));
  const missing = totals.reduce((s, t) => s + t.missing, 0);
  const plan: TripPlan = { primary: list.storeId, byStore: totals, total, missing, extraTravel, extraAreas: [...used.keys()], movedSavings, movedCount, suggestion, splitThreshold: threshold, recommendation: '' };
  plan.recommendation = recommend(plan, (id) => store(id)?.name || id, (a) => store(a)?.name || a);
  return plan;
}

const peso = (n: number) => (n < 0 ? '−₱' : '₱') + Math.abs(n).toFixed(2);

export function recommend(p: TripPlan, storeName: (id: string) => string, areaName: (a: string) => string): string {
  const primary = storeName(p.primary);
  if (p.movedCount) {
    const net = round2(p.movedSavings - p.extraTravel);
    const travel = p.extraTravel ? ` minus ${peso(p.extraTravel)} travel` : ' (no extra travel: same trip area)';
    return net > p.splitThreshold
      ? `Split is worth it: moved items save ${peso(p.movedSavings)}${travel} = ${peso(net)}.`
      : `Split saves ${peso(p.movedSavings)}${travel} = ${peso(net)}, under your ${peso(p.splitThreshold)} threshold. Consider buying all at ${primary}.`;
  }
  const s = p.suggestion;
  if (!s) return `Buy all at ${primary}.`;
  const to = s.storeIds.length === 1 ? storeName(s.storeIds[0]) : areaName(s.area);
  const travel = s.travel ? ` minus ${peso(s.travel)} travel` : ' (no extra travel)';
  return s.net > p.splitThreshold
    ? `Worth a split: moving ${s.lines} item${s.lines > 1 ? 's' : ''} to ${to} saves ${peso(s.savings)}${travel} = ${peso(s.net)}.`
    : `Buy all at ${primary}: moving ${s.lines} item${s.lines > 1 ? 's' : ''} to ${to} saves ${peso(s.savings)}${travel} = ${peso(s.net)}, under your ${peso(p.splitThreshold)} threshold.`;
}

/* ---------------------------------------------------------------- changes */

export function planNewList(view: View, storeId: string, date: string): { list: GroceryList; op: Op } {
  if (!storeId) throw new Error('Choose a store.');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) throw new Error('Choose a date.');
  const list: GroceryList = { id: newId('L', new Set(view.lists.map((l) => l.id))), date, storeId, status: 'Open' };
  return { list, op: { opId: newId('op'), type: 'list.upsert', list } };
}

/** Add an item to a list; if it is already there, add 1 (or `qty`) to that line instead. */
export function planAddToList(view: View, listId: string, itemId: string, qty = 1): { op: Op; merged: boolean; qty: number } {
  const cur = view.listLines.find((l) => l.listId === listId && l.itemId === itemId);
  if (cur) return { merged: true, qty: cur.qty + qty, op: { opId: newId('op'), type: 'listItem.upsert', item: { id: cur.id, qty: cur.qty + qty } } };
  const line: ListLine = { id: newId('LI', new Set(view.listLines.map((l) => l.id))), listId, itemId, qty, buyAt: '', notes: '', keep: false };
  return { merged: false, qty, op: { opId: newId('op'), type: 'listItem.upsert', item: line } };
}

export function planLineChange(line: ListLine, change: Partial<Pick<ListLine, 'qty' | 'buyAt' | 'keep' | 'itemId'>>): Op {
  return { opId: newId('op'), type: 'listItem.upsert', item: { id: line.id, ...change } };
}

/** Move a line to the cheaper store (BuyAt); switches to the cheaper pack when that is another item of the product. */
export function planMove(list: GroceryList, line: ListLine, c: Cheaper): Op {
  const change: Partial<ListLine> = { buyAt: c.point.storeId === list.storeId ? '' : c.point.storeId };
  if (c.item.id !== line.itemId) { change.itemId = c.item.id; change.qty = c.qty; }
  return planLineChange(line, change);
}

export function planRemove(line: ListLine): Op { return { opId: newId('op'), type: 'listItem.delete', id: line.id }; }
export function planListDone(list: GroceryList): Op { return { opId: newId('op'), type: 'list.upsert', list: { id: list.id, status: 'Done' } }; }

/** Items matching a search (name, brand, barcode, product name), best first. */
export function searchItems(view: View, q: string, limit = 8): Item[] {
  const words = q.toLowerCase().split(/\s+/).filter(Boolean);
  if (!words.length) return [];
  const hay = (it: Item) => {
    const size = it.packSize !== '' && it.packSize !== undefined ? `${it.packSize}${it.unit} ${it.packSize} ${it.unit}` : '';
    return [it.name, it.brand, it.barcode, size, it.productId ? view.productById.get(it.productId)?.name ?? '' : ''].join(' ').toLowerCase();
  };
  return view.items.filter((it) => { const h = hay(it); return words.every((w) => h.includes(w)); })
    .sort((a, b) => Number(!a.name.toLowerCase().startsWith(words[0])) - Number(!b.name.toLowerCase().startsWith(words[0])) || a.name.localeCompare(b.name))
    .slice(0, limit);
}
