/**
 * Products: groups of Items that are the same thing in different packs
 * (e.g. Queen baking soda 500 g and 1 kg). Pure helpers, unit-tested.
 */
import { newId } from './ids';
import { canonicalChoice, cleanText, distinctChoices } from './choices';
import type { Item, ItemFields, Op, Product } from './types';
import type { View } from './model';

/** Product names for the Product box, one per spelling, A–Z. */
export function productChoices(products: readonly Product[]): string[] {
  return distinctChoices(products.map((p) => p.name));
}

/**
 * Turns what was typed in the Product box into item fields:
 * blank → no product; an existing name (ignoring case/spaces) → its ID;
 * anything else → a new product (ID "PR" + 8 hex) created with the item.
 */
export function resolveProduct(view: View, typed: string, standardUnit: string, makeId = () => newId('PR', view.productById)):
  Pick<ItemFields, 'productId' | 'product'> {
  const name = cleanText(typed);
  if (!name) return { productId: '' };
  const spelled = canonicalChoice(productChoices(view.products), name);
  const found = view.products.find((p) => cleanText(p.name).toLowerCase() === spelled.toLowerCase());
  if (found) return { productId: found.id };
  const id = makeId();
  return { productId: id, product: { id, name, standardUnit } };
}

const STOP = new Set(['per', 'pcs', 'pack', 'the', 'and', 'with', 'for', 'buy', 'new', 'size']);

/** Name words that identify a product: letters only, 3+ long, sizes and filler dropped. */
export function nameWords(s: string): Set<string> {
  return new Set((s.toLowerCase().match(/[a-z]+/g) ?? []).filter((w) => w.length >= 3 && !STOP.has(w)));
}

function overlap(a: Set<string>, b: Set<string>): number {
  if (!a.size || !b.size) return 0;
  let n = 0;
  a.forEach((w) => { if (b.has(w)) n++; });
  return n / (a.size + b.size - n);
}

/**
 * A product this item probably belongs to, to offer (never to pick silently):
 * a product whose name words are all in the item's name + brand, or the
 * product of the most similar already-grouped item (same brand counts extra).
 */
export function suggestProduct(view: View, name: string, brand: string, exceptItemId?: string): Product | undefined {
  const words = nameWords(name + ' ' + brand);
  if (!words.size) return undefined;
  let best: Product | undefined;
  let score = 0;
  for (const p of view.products) {
    const pw = nameWords(p.name);
    if (pw.size && [...pw].every((w) => words.has(w)) && 0.9 > score) { best = p; score = 0.9; }
  }
  const b = cleanText(brand).toLowerCase();
  for (const it of view.items) {
    if (it.id === exceptItemId || !it.productId) continue;
    const p = view.productById.get(it.productId);
    if (!p) continue;
    const s = overlap(nameWords(it.name + ' ' + it.brand), words) + (b && cleanText(it.brand).toLowerCase() === b ? 0.15 : 0);
    if (s > score) { best = p; score = s; }
  }
  return score >= 0.5 ? best : undefined;
}

/** Saving the edit form: the editable fields of an existing item (sending them again is harmless). */
export function planEditItem(item: Item, fields: Omit<ItemFields, 'id' | 'barcode'>): Op {
  return { opId: newId('op'), type: 'item.upsert', item: { id: item.id, ...fields } };
}

/* ---------------------------------------------------------------- matching (Product box) */

/** Lower case, accents removed (é → e, ñ → n). */
export function fold(s: string): string {
  return String(s ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
}

/** Simple English singular: tissues → tissue, berries → berry, boxes → box; "glass", "bus", "gas" kept. */
export function singular(w: string): string {
  if (w.length > 4 && w.endsWith('ies')) return w.slice(0, -3) + 'y';
  if (w.length > 4 && /(ches|shes|xes|sses|zes)$/.test(w)) return w.slice(0, -2);
  if (w.length > 3 && w.endsWith('s') && !/(ss|us|is|as)$/.test(w)) return w.slice(0, -1);
  return w;
}

/** Words of a text: folded, split on anything not a letter or digit, singular. */
export function words(s: string): string[] {
  return (fold(s).match(/[a-z0-9]+/g) ?? []).map(singular);
}

const UNIT_WORDS = new Set(['g', 'kg', 'mg', 'ml', 'l', 'pc', 'piece', 'doz', 'dozen', 'pull', 'sheet', 'ply', 'tab', 'cap', 'sachet', 'bottle',
  'can', 'box', 'bag', 'pack', 'oz', 'lb', 'x']);
const FILLER = new Set(['per', 'the', 'and', 'with', 'for', 'buy', 'new', 'size', 'big', 'small', 'mini', 'travel', 'refill', 'on', 'go',
  'of', 'in', 'a', 'an', 'pure', 'original', 'classic', 'value', 'promo', 'free', 'take', 'out', 'twin', 'bundle']);

/** Words that say what a thing is: no brands, sizes, units, numbers or filler. */
export function meaningfulWords(text: string, brands: readonly string[] = []): string[] {
  const skip = new Set(brands.flatMap((b) => words(b)));
  return [...new Set(words(text).filter((w) => w.length >= 3 && !/\d/.test(w) && !UNIT_WORDS.has(w) && !FILLER.has(w) && !skip.has(w)))];
}

/** "2 items · per pull" for a Product. */
export function productDescribe(view: View, p: Product): string {
  const n = view.items.filter((i) => i.productId === p.id).length;
  const u = p.standardUnit || '';
  const per = u ? 'per ' + (u === 'L' ? 'L' : singular(u.toLowerCase())) : '';
  return [`${n} item${n === 1 ? '' : 's'}`, per].filter(Boolean).join(' · ');
}

interface Hay { name: string[]; members: string[] }
function haystack(view: View, p: Product): Hay {
  const members = view.items.filter((i) => i.productId === p.id)
    .flatMap((i) => words([i.name, i.brand, i.packSize !== '' && i.packSize !== undefined ? `${i.packSize}${i.unit} ${i.packSize} ${i.unit}` : ''].join(' ')));
  return { name: words(p.name), members };
}

/** How well one typed word matches a list of words: whole word 3, start of a word 2, inside a word 1, else 0. */
function wordScore(q: string, ws: readonly string[]): number {
  let best = 0;
  for (const w of ws) {
    if (w === q) return 3;
    if (w.startsWith(q)) best = Math.max(best, 2);
    else if (q.length >= 3 && w.includes(q)) best = Math.max(best, 1);
  }
  return best;
}

/**
 * Products for what is typed in the Product box: every typed word (any order, partial,
 * plural, case and accents ignored) must match the Product's name or one of its items'
 * names, brands or sizes. Whole-word and start-of-word matches in the Product name rank first.
 */
export function searchProducts(view: View, typed: string): Product[] {
  const qs = words(typed);
  if (!qs.length) return [...view.products];
  const scored: { p: Product; s: number }[] = [];
  for (const p of view.products) {
    const hay = haystack(view, p);
    let total = 0, ok = true;
    for (const q of qs) {
      const inName = wordScore(q, hay.name), inItems = wordScore(q, hay.members);
      const s = Math.max(inName * 2, inItems);           // a match in the Product's own name counts double
      if (!s) { ok = false; break; }
      total += s;
    }
    if (ok) scored.push({ p, s: total });
  }
  return scored.sort((a, b) => b.s - a.s || a.p.name.localeCompare(b.p.name)).map((x) => x.p);
}

/**
 * Products that share meaningful words (not brands, sizes, units or filler) with a name,
 * closest first, for "Same product as …?" and "Did you mean …?". Never picks one itself.
 */
export function similarProducts(view: View, name: string, brand = '', max = 3, exceptProductId = ''): Product[] {
  const brands = [brand, ...view.items.map((i) => i.brand)].filter(Boolean);
  const mine = meaningfulWords(name, brands);
  if (!mine.length) return [];
  const scored: { p: Product; s: number }[] = [];
  for (const p of view.products) {
    if (p.id === exceptProductId) continue;
    const pw = meaningfulWords(p.name, brands);
    const memberW = new Set(view.items.filter((i) => i.productId === p.id).flatMap((i) => meaningfulWords(i.name, brands)));
    let s = 0;
    for (const w of mine) {
      if (pw.includes(w)) s += 2;
      else if (memberW.has(w)) s += 1;
    }
    if (s > 0) scored.push({ p, s: s / Math.max(pw.length, 1) + s / 10 });
  }
  return scored.sort((a, b) => b.s - a.s || a.p.name.localeCompare(b.p.name)).slice(0, max).map((x) => x.p);
}

/** The Product a typed name means exactly (case, accents and spaces ignored), if any. */
export function productByName(view: View, typed: string): Product | undefined {
  const k = fold(cleanText(typed));
  return k ? view.products.find((p) => fold(cleanText(p.name)) === k) : undefined;
}

const sameUnit = (a: string, b: string) => !a || !b || a.trim().toLowerCase() === b.trim().toLowerCase();

/**
 * What to ask before saving the Product box: "Did you mean …?" when a new Product would be
 * created while close ones exist (unless `confirmedNew` is that name), or a unit warning when
 * the picked Product compares per another unit (unless `confirmedUnit` is that Product's id).
 */
export function productCheck(view: View, typed: string, itemName: string, brand: string, standardUnit: string,
  confirmedNew = '', confirmedUnit = ''): { kind: 'ok' } | { kind: 'didYouMean'; name: string; matches: Product[] } | { kind: 'unit'; product: Product } {
  const name = cleanText(typed);
  if (!name) return { kind: 'ok' };
  const found = productByName(view, name);
  if (found) {
    if (!sameUnit(found.standardUnit, standardUnit) && confirmedUnit !== found.id) return { kind: 'unit', product: found };
    return { kind: 'ok' };
  }
  if (fold(confirmedNew) === fold(name)) return { kind: 'ok' };
  const seen = new Set<string>();
  const matches = [...searchProducts(view, name), ...similarProducts(view, name + ' ' + itemName, brand, 3)]
    .filter((p) => !seen.has(p.id) && seen.add(p.id)).slice(0, 4);
  return matches.length ? { kind: 'didYouMean', name, matches } : { kind: 'ok' };
}
