/**
 * ⓘ buttons, the field popup and the "How cheapest works" page. Both open as an overlay
 * above the current screen, so a half-filled form is never lost; Back closes them.
 */
import { h } from '../dom';
import { FIELD_HELP, perUnitExample, type HelpKey } from '../core/helpText';
import { FRESH_DAYS, PROMO_DAYS, unitFactor } from '../core/compare';

let overlay: HTMLElement | null = null;
let ignoreNextPop = false;

/** Call first in the app's popstate handler: true when the event was the help overlay's. */
export function helpOnPop(): boolean {
  if (ignoreNextPop) { ignoreNextPop = false; return true; }
  if (overlay) { overlay.remove(); overlay = null; return true; }
  return false;
}

export function closeHelp() {
  if (!overlay) return;
  overlay.remove(); overlay = null;
  if (history.state?.help) { ignoreNextPop = true; history.back(); }
}

function show(content: HTMLElement, page: boolean) {
  const fresh = !overlay;
  overlay?.remove();
  overlay = h('div', { class: page ? 'modal help-page' : 'help-pop', role: 'dialog', 'aria-modal': 'true', 'aria-label': page ? 'How cheapest works' : 'Field help',
    onclick: (e: Event) => { if (e.target === overlay) closeHelp(); } }, content);
  document.body.append(overlay);
  if (fresh) history.pushState({ ...(history.state ?? {}), help: true }, '');
  overlay.querySelector<HTMLElement>('.help-close')?.focus();
}

const closeBtn = () => h('button', { class: 'chip help-close', type: 'button', onclick: closeHelp, 'aria-label': 'Close help' }, '✕ Close');

export function openFieldHelp(key: HelpKey) {
  const f = FIELD_HELP[key];
  show(h('div', { class: 'card help-card' },
    h('div', { class: 'help-head' }, h('h2', {}, f.title), closeBtn()),
    h('p', {}, f.what),
    h('dl', { class: 'help-dl' },
      h('dt', {}, 'Saved to'), h('dd', {}, f.saves),
      h('dt', {}, 'Cheapest'), h('dd', {}, f.cheapest),
      h('dt', {}, 'Examples'), h('dd', {}, h('ul', {}, f.examples.map((x) => h('li', {}, x))))),
    h('button', { class: 'link-btn', type: 'button', onclick: () => openCheapestHelp() }, 'How cheapest works ›')), false);
}

/** A small ⓘ for a field caption. Stops the tap from reaching the label or box around it. */
export function helpBtn(key: HelpKey) {
  return h('button', { class: 'help-i', type: 'button', 'aria-label': `About ${FIELD_HELP[key].title}`,
    onclick: (e: Event) => { e.preventDefault(); e.stopPropagation(); openFieldHelp(key); } }, 'ⓘ');
}

/** Caption text followed by its ⓘ. */
export function cap(text: string, key: HelpKey) {
  return h('span', { class: 'cap' }, text, ' ', helpBtn(key));
}

export function openCheapestHelp(staleDays = 60) {
  const pepper = perUnitExample(42, 30, unitFactor('g'));
  const other = perUnitExample(55, 33, unitFactor('g'));
  const fmt = (n: number) => '₱' + n.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  const sec = (title: string, ...body: (HTMLElement | string)[]) => h('section', { class: 'help-sec' }, h('h2', {}, title), ...body);
  show(h('main', { class: 'screen' },
    h('header', { class: 'bar' }, h('h1', { class: 'small' }, 'How cheapest works'), closeBtn()),
    sec('Price per unit',
      h('p', {}, 'Per-unit price = price ÷ (pack size × unit factor).'),
      h('p', { class: 'muted' }, 'Unit factor: g and mL = 0.001 (so prices are per kg / per L), doz = 12 (per piece), anything else = 1. The pack size is this purchase\'s pack, else the item\'s usual pack. Same rule in the app and in the sheet\'s LatestPrices tab.')),
    sec('Worked example',
      h('p', {}, `J & Y ground white pepper 30 g at ₱42 (WalterMart Taytay, Oct 23): 42 ÷ (30 × 0.001) = ${fmt(pepper)}/kg.`),
      h('p', {}, `Example only, not real data: another brand, 33 g at ₱55 = ${fmt(other)}/kg. The J & Y pack is cheaper per kg, even though both are small packs.`)),
    sec('Products: brands and sizes together',
      h('p', {}, 'A Product groups items that are the same thing in different brands or pack sizes. Inside a Product, items are compared per compare-by unit, but only items with that same unit and a pack size. An item without a Product is compared only with itself at other stores.'),
      h('p', {}, h('strong', {}, 'Name Products generically: '), '"Ground white pepper", not "J & Y ground white pepper", so every brand can join it.')),
    sec('Cheapest store, pack or brand',
      h('ul', {},
        h('li', {}, h('strong', {}, 'Cheapest store: '), 'the same item at each store (sheet tab ItemBest; "Cheapest" on the price card).'),
        h('li', {}, h('strong', {}, 'Cheapest pack: '), 'another size of the same Product, per unit ("Cheaper pack here" in Lists; ProductBest tab).'),
        h('li', {}, h('strong', {}, 'Cheapest brand: '), 'another brand in the same Product. "Same product" in Lists and on the price card shows this item\'s cheapest store, the cheapest other brand of the same size, and the cheapest of any size.'))),
    sec('Old prices and promos',
      h('p', {}, `Prices up to ${FRESH_DAYS} days old are fresh, then ageing; after ${staleDays} days (Settings PriceStaleDays) they are old: still shown, but not used for "cheaper at" or "Same product".`),
      h('p', {}, `A promo older than ${PROMO_DAYS} days may have ended, so the newest regular price at that store is used instead (if it isn't old).`),
      h('p', { class: 'muted' }, 'The sheet\'s ItemBest and ProductBest tabs simply use each store\'s newest price, without these age rules.')),
    sec('Trips and travel (Plan and Lists)',
      h('p', {}, 'Stores with the same BranchArea on the Stores tab are one trip area: moving items between them adds no travel. Each other area adds one round-trip fare: the highest TranspoCostRoundTrip among its stores.'),
      h('p', {}, 'A list suggests a split only when the savings minus that travel are more than Settings SplitThreshold (₱50 by default).')),
  ), true);
}
