/**
 * Pick-or-type lists for the brand and unit boxes (pure, unit-tested).
 * Values are compared ignoring case and extra spaces, so "queen" and
 * "Queen " are one brand; the list shows one spelling for each.
 */

/** Trims and collapses inner whitespace. */
export function cleanText(s: string | null | undefined): string {
  return String(s ?? '').replace(/\s+/g, ' ').trim();
}

const keyOf = (s: string) => cleanText(s).toLocaleLowerCase();
const byName = (a: string, b: string) => a.localeCompare(b, undefined, { sensitivity: 'base' }) || a.localeCompare(b);

/**
 * Distinct values, A–Z. For each value the spelling shown is the one in
 * `preferred` if it is there, otherwise the most common spelling in
 * `values` (ties: the first one seen).
 */
export function distinctChoices(values: readonly string[], preferred: readonly string[] = []): string[] {
  const groups = new Map<string, { counts: Map<string, number>; order: string[]; fixed?: string }>();
  const group = (k: string) => {
    let g = groups.get(k);
    if (!g) { g = { counts: new Map(), order: [] }; groups.set(k, g); }
    return g;
  };
  for (const raw of preferred) {
    const s = cleanText(raw); if (!s) continue;
    const g = group(keyOf(s)); g.fixed ??= s;
  }
  for (const raw of values) {
    const s = cleanText(raw); if (!s) continue;
    const g = group(keyOf(s));
    if (!g.counts.has(s)) g.order.push(s);
    g.counts.set(s, (g.counts.get(s) ?? 0) + 1);
  }
  const out: string[] = [];
  for (const g of groups.values()) {
    if (g.fixed) { out.push(g.fixed); continue; }
    let best = g.order[0], n = -1;
    for (const s of g.order) { const c = g.counts.get(s)!; if (c > n) { best = s; n = c; } }
    out.push(best);
  }
  return out.sort(byName);
}

/** Brands already used in Items (including ones saved on this device and not yet synced). */
export function brandChoices(items: readonly { brand: string }[]): string[] {
  return distinctChoices(items.map((i) => i.brand));
}

/**
 * Options matching what was typed: options that start with it (or have a
 * word that does) first, then ones that contain it; each group keeps A–Z.
 * Nothing typed: every option.
 */
export function filterChoices(options: readonly string[], typed: string): string[] {
  const q = keyOf(typed);
  if (!q) return [...options];
  const starts: string[] = [], contains: string[] = [];
  for (const o of options) {
    const k = o.toLocaleLowerCase();
    if (k.startsWith(q) || k.split(/[\s\-/&+.]+/).some((w) => w.startsWith(q))) starts.push(o);
    else if (k.includes(q)) contains.push(o);
  }
  return [...starts, ...contains];
}

/** What to save for typed text: the list's spelling when it matches one (ignoring case/spaces), else the cleaned text. */
export function canonicalChoice(options: readonly string[], typed: string): string {
  const s = cleanText(typed);
  const k = keyOf(s);
  return options.find((o) => keyOf(o) === k) ?? s;
}

/** True when the typed text is not (yet) one of the options. */
export function isNewChoice(options: readonly string[], typed: string): boolean {
  const k = keyOf(typed);
  return !!k && !options.some((o) => keyOf(o) === k);
}
