import { distinctChoices, cleanText } from './choices';

/** Count units that compare per piece (existing data: doz, tab and cap items have StandardUnit pc). */
const COUNT_UNITS = ['pc', 'pcs', 'piece', 'doz', 'tab', 'cap'];
export const STANDARD_UNITS = ['kg', 'L', 'pc'];

/**
 * Standard unit for comparing prices, following the existing Items data:
 * g/kg → kg, mL/L → L, known count units → pc. A unit the app has never
 * seen (pack, box, sachet, bottle…) is its own standard unit, so a "pack"
 * item is compared per pack, never mixed up with per-piece prices.
 */
export function standardUnitFor(unit: string): string {
  const u = cleanText(unit);
  const k = u.toLowerCase();
  if (!u) return 'pc';
  if (k === 'g' || k === 'kg') return 'kg';
  if (k === 'ml' || k === 'l') return 'L';
  if (COUNT_UNITS.includes(k)) return 'pc';
  return u;
}

/** Choices for the standard-unit box: kg / L / pc, plus the unit itself when it is its own standard. */
export function standardUnitChoices(unit: string): string[] {
  const own = standardUnitFor(unit);
  return STANDARD_UNITS.includes(own) ? [...STANDARD_UNITS] : [...STANDARD_UNITS, own];
}

/**
 * Units offered in the unit boxes: the Units tab plus every unit already used
 * in Items and on price lines, one spelling each (the Units tab's), A–Z.
 */
export function unitChoices(unitsTab: readonly string[], usedUnits: readonly string[]): string[] {
  return distinctChoices([...unitsTab, ...usedUnits], unitsTab);
}
