/**
 * Receipt mode. A receipt is edited as a draft on this device only, then
 * saved whole with one receipt.save (header + lines + payments) at Done, paid
 * or not (Apps Script v6+). The budget feed posts a receipt only once its Total
 * is > 0 and its payments reach it, so unpaid ones stay out of the budget until
 * paid; overpaying is warned about. All money is handled in centavos.
 */
import { newId } from './ids';
import { findOpenLine, priceHere, type View } from './model';
import type { Item, Op, Receipt, ReceiptSave } from './types';

export interface DraftLine {
  id: string; itemId: string; price: number | ''; qty: number; packSize: number | ''; packUnit: string;
  promo: boolean; notes: string; barcode: string;
  /** Weighed goods: qty 1 and the weight as pack size (how the sheet records them). */
  weighed?: boolean;
}
export interface DraftPayment { id: string; account: string; amount: number }
export interface ReceiptDraft {
  id: string;
  /** The receipt is already in the sheet (this draft edits it). */
  saved: boolean;
  date: string; storeId: string; fallbackCategory: string; notes: string;
  /** What was typed in the Discount box, e.g. "68.3+113.84" ('' = no discount). */
  discountEntry: string;
  lines: DraftLine[];
  payments: DraftPayment[];
  /** Lines that were on the saved receipt (edit only). */
  savedLineIds: string[];
  /** Saved lines removed as wrong scans: deleted from Prices on save. Others that leave stay as price sightings. */
  deleteLineIds: string[];
  startedAt: number;
  /** Fingerprint of the saved receipt when this edit started (drafts from before 28 Oct don't have it). */
  base?: string;
}

export const toCents = (n: number) => Math.round(n * 100);
export const pesos = (c: number) => c / 100;

/** Line amount in centavos: price × qty (blank/0 qty = 1), rounded to the centavo. */
export function lineCents(l: Pick<DraftLine, 'price' | 'qty'>): number {
  if (l.price === '' || !(l.price > 0)) return 0;
  const q = l.qty > 0 ? l.qty : 1;
  return Math.round(toCents(l.price) * q);
}

/** "68.3+113.84", "90.07", "" → centavos; null if it isn't amounts joined by +. */
export function parseDiscountEntry(raw: string): number | null {
  const s = raw.replace(/[\s,₱]/g, '');
  if (!s) return 0;
  if (!/^\d+(\.\d{1,2})?(\+\d+(\.\d{1,2})?)*$/.test(s)) return null;
  return s.split('+').reduce((t, x) => t + toCents(Number(x)), 0);
}

/** Discount entry as saved in DiscountEntry (K): spaces, commas and ₱ removed. */
export function cleanEntry(raw: string): string { return raw.replace(/[\s,₱]/g, ''); }

export interface Totals {
  lines: number; discount: number | null; total: number; paid: number; left: number;
}

export function totals(d: ReceiptDraft): Totals {
  const lines = d.lines.reduce((t, l) => t + lineCents(l), 0);
  const discount = parseDiscountEntry(d.discountEntry);
  const total = lines - (discount ?? 0);
  const paid = d.payments.reduce((t, p) => t + toCents(p.amount || 0), 0);
  return { lines, discount, total, paid, left: total - paid };
}

/**
 * PWD / senior citizen: VAT exemption = shelf total × 12/112, then 20% off what
 * is left. Matches Albert's receipts: 637.50 → 68.30 + 113.84; 315.25 → 33.78 + 56.29.
 */
export function pwdDiscount(grossCents: number): { vat: number; pct: number; entry: string } {
  const vat = Math.round((grossCents * 12) / 112);
  const pct = Math.round((grossCents - vat) * 0.2);
  return { vat, pct, entry: `${pesos(vat)}+${pesos(pct)}` };
}

const op = () => newId('op');

export function receiptsByDate(view: View): Receipt[] {
  return [...view.receipts].sort((a, b) => b.date.localeCompare(a.date) || b.id.localeCompare(a.id));
}

/** "Today", "Yesterday" or e.g. "Tue, Oct 27, 2026" for a yyyy-mm-dd date. */
export function dayLabel(date: string, today: string): string {
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(date);
  if (!m) return date || 'No date';
  const t = /^(\d{4})-(\d{2})-(\d{2})$/.exec(today);
  const utc = (y: string, mo: string, d: string) => Date.UTC(+y, +mo - 1, +d);
  if (t) {
    const days = Math.round((utc(t[1], t[2], t[3]) - utc(m[1], m[2], m[3])) / 86400000);
    if (days === 0) return 'Today';
    if (days === 1) return 'Yesterday';
  }
  return new Date(utc(m[1], m[2], m[3])).toLocaleDateString('en-US', { weekday: 'short', month: 'short', day: 'numeric', year: 'numeric', timeZone: 'UTC' });
}

/**
 * Saved receipts grouped by date, newest date first. Within a day, newest saved first:
 * receipts still waiting to sync, then by TotalRefreshedAt (J), then later sheet rows first.
 */
export function receiptsByDay(view: View, today: string, pendingIds: Set<string> = new Set()): { date: string; label: string; receipts: Receipt[] }[] {
  const pos = new Map(view.receipts.map((r, i) => [r.id, i] as const));
  const rank = (r: Receipt) => [pendingIds.has(r.id) ? 1 : 0, Date.parse(r.refreshedAt ?? '') || 0, pos.get(r.id) ?? 0];
  const sorted = [...view.receipts].sort((a, b) => {
    if (a.date !== b.date) return b.date.localeCompare(a.date);
    const x = rank(a), y = rank(b);
    return y[0] - x[0] || y[1] - x[1] || y[2] - x[2];
  });
  const out: { date: string; label: string; receipts: Receipt[] }[] = [];
  for (const r of sorted) {
    const last = out[out.length - 1];
    if (last && last.date === r.date) last.receipts.push(r);
    else out.push({ date: r.date, label: dayLabel(r.date, today), receipts: [r] });
  }
  return out;
}

/** The store's DefaultCategory if it's a Category, else the category of the last receipt there. */
export function defaultCategory(view: View, storeId: string): string {
  const st = view.stores.find((s) => s.id === storeId);
  if (st?.defaultCategory && view.categories.includes(st.defaultCategory)) return st.defaultCategory;
  const last = receiptsByDate(view).find((r) => r.storeId === storeId && view.categories.includes(r.fallbackCategory));
  return last?.fallbackCategory ?? '';
}

/** Account of the last receipt at this store, else the last account used anywhere ('' if none or not in Accounts). */
export function defaultAccount(view: View, storeId: string): string {
  const rs = receiptsByDate(view);
  for (const pick of [rs.filter((r) => r.storeId === storeId), rs]) {
    for (const r of pick) {
      const p = view.payments.find((x) => x.receiptId === r.id && view.accounts.includes(x.account));
      if (p) return p.account;
    }
  }
  return '';
}

/** Accounts: the store's usual one first, then the most used, then A–Z. */
export function accountChoices(view: View, storeId: string): string[] {
  const first = defaultAccount(view, storeId);
  const used = new Map<string, number>();
  view.payments.forEach((p) => used.set(p.account, (used.get(p.account) ?? 0) + 1));
  const rest = [...view.accounts].sort((a, b) => (used.get(b) ?? 0) - (used.get(a) ?? 0) || a.localeCompare(b, undefined, { sensitivity: 'base' })).filter((a) => a !== first);
  return first ? [first, ...rest] : rest;
}

export function newDraft(view: View, storeId: string, date: string, now = Date.now()): ReceiptDraft {
  const taken = new Set(view.receipts.map((r) => r.id));
  return {
    id: newId('R', taken), saved: false, date, storeId, fallbackCategory: defaultCategory(view, storeId), notes: '',
    discountEntry: '', lines: [], payments: [], savedLineIds: [], deleteLineIds: [], startedAt: now,
  };
}

/** A saved receipt opened for editing. */
export function draftFromSaved(view: View, r: Receipt, now = Date.now()): ReceiptDraft {
  const lines = view.receiptLines.filter((l) => l.receiptId === r.id);
  const entry = r.discountEntry || (r.discount !== '' && r.discount > 0 ? String(r.discount) : '');
  return {
    id: r.id, saved: true, date: r.date, storeId: r.storeId, fallbackCategory: r.fallbackCategory, notes: r.notes, discountEntry: entry,
    lines: lines.map((l) => ({ id: l.id, itemId: l.itemId, price: l.price, qty: l.qty === '' || !(l.qty > 0) ? 1 : l.qty, packSize: l.packSize,
      packUnit: l.packUnit, promo: l.promo, notes: l.notes, barcode: l.barcode })),
    payments: view.payments.filter((p) => p.receiptId === r.id).map((p) => ({ id: p.id, account: p.account, amount: p.amount === '' ? 0 : p.amount })),
    savedLineIds: lines.map((l) => l.id), deleteLineIds: [], startedAt: now,
  };
}

/** A saved receipt opened for editing, remembering what it looked like then. */
export function editSaved(view: View, r: Receipt, now = Date.now()): ReceiptDraft {
  const d = draftFromSaved(view, r, now);
  d.base = draftKey(d);
  return d;
}

/** What matters in a receipt (header, lines, discount, payments), as one comparable string. */
export function draftKey(d: ReceiptDraft): string {
  const c = (n: number | '') => (n === '' ? '' : toCents(n));
  return JSON.stringify([d.date, d.storeId, d.fallbackCategory, d.notes.trim(), cleanEntry(d.discountEntry),
    d.lines.map((l) => [l.id, l.itemId, c(l.price), l.qty > 0 ? l.qty : 1, l.packSize, l.packUnit, !!l.promo, l.notes]).sort(),
    d.payments.map((p) => [p.account, toCents(p.amount)]).sort()]);
}

/**
 * How an edit kept on this phone compares with the saved receipt:
 * 'same' (nothing to lose), 'changed' (unsaved changes), 'gone' (no longer in the sheet),
 * or 'new' (a receipt never saved). `savedMoved`: the saved receipt changed since this edit began.
 */
export function compareWithSaved(view: View, d: ReceiptDraft): { state: 'new' | 'same' | 'changed' | 'gone'; savedMoved: boolean; saved?: Receipt } {
  if (!d.saved) return { state: 'new', savedMoved: false };
  const saved = view.receipts.find((r) => r.id === d.id);
  if (!saved) return { state: 'gone', savedMoved: false };
  const now = draftKey(draftFromSaved(view, saved));
  return { state: draftKey(d) === now ? 'same' : 'changed', savedMoved: d.base !== undefined && d.base !== now, saved };
}

function lineTaken(view: View, d: ReceiptDraft) {
  return { has: (id: string) => d.lines.some((l) => l.id === id) || view.openLines.some((l) => l.id === id) || view.receiptLines.some((l) => l.id === id) };
}

/**
 * A scanned or picked item. Already on this receipt: one more of it.
 * Otherwise a new line: today's unlinked line for it at this store (same
 * item + store + date) is taken over; the price starts at the last price here.
 */
export function addItem(view: View, d: ReceiptDraft, item: Item, barcode: string): { line: DraftLine; merged: boolean } {
  const have = d.lines.find((l) => l.itemId === item.id);
  if (have && !have.weighed) { have.qty += 1; return { line: have, merged: true }; }
  const open = findOpenLine(view, item.id, d.storeId, d.date);
  const here = priceHere(view, item.id, d.storeId);
  const line: DraftLine = {
    id: open && !d.lines.some((l) => l.id === open.id) ? open.id : newId('P', lineTaken(view, d)),
    itemId: item.id,
    price: open?.price !== undefined && open.price !== '' ? open.price : here?.price ?? '',
    qty: 1,
    packSize: open?.packSize ?? (item.packSize !== '' ? item.packSize : item.lastPackSize),
    packUnit: open?.packUnit || item.unit,
    promo: open?.promo ?? false,
    notes: open?.notes ?? '',
    barcode: barcode || item.barcode,
  };
  d.lines.push(line);
  return { line, merged: false };
}

/** Removes a line. On a saved receipt, `wrongScan` deletes its Prices row; otherwise it stays as a price sighting. */
export function removeLine(d: ReceiptDraft, lineId: string, wrongScan: boolean) {
  d.lines = d.lines.filter((l) => l.id !== lineId);
  if (wrongScan && d.savedLineIds.includes(lineId) && !d.deleteLineIds.includes(lineId)) d.deleteLineIds.push(lineId);
}

/** "Pay the rest with" chips: up to 3 accounts (store's usual first, then most used); label is just the name. */
export function restChips(view: View, d: ReceiptDraft, max = 3): { account: string; label: string; ariaLabel: string }[] {
  const left = totals(d).left;
  if (!(left > 0)) return [];
  const amount = (left / 100).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  return accountChoices(view, d.storeId).slice(0, max)
    .map((a) => ({ account: a, label: a, ariaLabel: `Pay the remaining ₱${amount} with ${a}` }));
}

/** The payments box: its heading and the one status line under it. */
export function paymentStatus(d: ReceiptDraft): { heading: string; status: string; state: 'ok' | 'warn' | '' } {
  const t = totals(d);
  const heading = d.payments.length ? 'Paid with' : 'Pay with';
  if (t.discount === null || t.total <= 0) return { heading, status: '', state: '' };
  const fmt = (c: number) => '₱' + (c / 100).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  if (t.left > 0) return { heading, status: `${fmt(t.left)} still unpaid`, state: 'warn' };
  if (t.left < 0) return { heading, status: `Paid ${fmt(-t.left)} more than the total`, state: 'warn' };
  return { heading, status: '✓ Paid in full', state: 'ok' };
}

/** One tap: whatever is still unpaid goes on `account` (added to its payment, or a new one). */
export function restOn(view: View, d: ReceiptDraft, account: string) {
  const t = totals(d);
  if (t.left <= 0 || !account) return;
  const p = d.payments.find((x) => x.account === account);
  if (p) p.amount = pesos(toCents(p.amount) + t.left);
  else d.payments.push({ id: newId('PM', { has: (id) => d.payments.some((x) => x.id === id) || view.payments.some((x) => x.id === id) }), account, amount: pesos(t.left) });
}

export function addPayment(view: View, d: ReceiptDraft, account: string, amount: number) {
  d.payments.push({ id: newId('PM', { has: (id) => d.payments.some((x) => x.id === id) || view.payments.some((x) => x.id === id) }), account, amount });
}

/**
 * What still stops Done (empty = ready). The balance never blocks with Apps Script v6+ (a receipt
 * saves unpaid, part-paid or overpaid); an older script still refuses anything but exactly paid.
 */
export function draftProblems(view: View, d: ReceiptDraft, includeBalance = true): string[] {
  const out: string[] = [];
  if (!view.stores.some((s) => s.id === d.storeId)) out.push('Choose a store.');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(d.date)) out.push('Choose a date.');
  if (!view.categories.includes(d.fallbackCategory)) out.push('Choose a category.');
  if (!d.lines.length) out.push('Add at least one item.');
  const noPrice = d.lines.filter((l) => l.price === '' || !(l.price > 0));
  if (noPrice.length) out.push(`${noPrice.length} line${noPrice.length > 1 ? 's have' : ' has'} no price.`);
  const t = totals(d);
  if (t.discount === null) out.push('Discount must be amounts joined by +, e.g. 68.3+113.84.');
  else if (d.lines.length && t.total <= 0) out.push('The discount is more than the items.');
  const badAcct = d.payments.filter((p) => !view.accounts.includes(p.account));
  if (badAcct.length) out.push('Pick an account for every payment.');
  if (d.payments.some((p) => !(p.amount > 0))) out.push('Every payment needs an amount.');
  if (includeBalance && !view.unpaidSaves && t.discount !== null && t.total > 0) {
    const old = ' (the Apps Script is older than v6, so the receipt must be paid exactly)';
    if (t.left > 0) out.push(`₱${pesos(t.left).toFixed(2)} still unpaid${old}.`);
    if (t.left < 0) out.push(`Payments are ₱${pesos(-t.left).toFixed(2)} more than the total${old}.`);
  }
  return out;
}

export function planReceiptSave(d: ReceiptDraft): Op {
  const t = totals(d);
  const receipt: ReceiptSave = {
    id: d.id, date: d.date, storeId: d.storeId, fallbackCategory: d.fallbackCategory, notes: d.notes.trim(),
    discount: pesos(t.discount ?? 0), discountEntry: cleanEntry(d.discountEntry), total: pesos(t.total),
    lines: d.lines.map((l) => ({ id: l.id, itemId: l.itemId, price: l.price as number, qty: l.qty > 0 ? l.qty : 1, packSize: l.packSize,
      packUnit: l.packUnit, promo: l.promo, notes: l.notes, barcode: l.barcode })),
    payments: d.payments.map((p) => ({ id: p.id, account: p.account, amount: pesos(toCents(p.amount)) })),
  };
  const del = d.deleteLineIds.filter((id) => !d.lines.some((l) => l.id === id));
  if (del.length) receipt.deleteLineIds = del;
  return { opId: op(), type: 'receipt.save', receipt };
}

export function planReceiptDelete(id: string): Op {
  return { opId: op(), type: 'receipt.delete', id };
}

/** Paid in full by its ReceiptPayments (what the budget feed checks). */
/** A saved receipt's balance: paid exactly, unpaid (amount left, in centavos) or overpaid (extra). */
export function payState(view: View, r: Receipt): { state: 'paid' | 'unpaid' | 'overpaid'; cents: number; label: string } {
  const total = r.total === '' ? 0 : toCents(r.total);
  const paid = view.payments.filter((p) => p.receiptId === r.id).reduce((t, p) => t + toCents(p.amount === '' ? 0 : p.amount), 0);
  const fmt = (c: number) => '₱' + (c / 100).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  if (paid === total) return { state: 'paid', cents: 0, label: 'paid' };
  if (paid < total) return { state: 'unpaid', cents: total - paid, label: paid ? `${fmt(total - paid)} left to pay` : `unpaid, ${fmt(total)} left` };
  return { state: 'overpaid', cents: paid - total, label: `Paid ${fmt(paid - total)} more than the total` };
}

export function isPaid(view: View, r: Receipt): boolean {
  if (r.total === '' || !(r.total > 0)) return false;
  const paid = view.payments.filter((p) => p.receiptId === r.id).reduce((t, p) => t + toCents(p.amount === '' ? 0 : p.amount), 0);
  return paid >= toCents(r.total);
}

/** Fin's import windows: tabs at 90% or more of the rows the budget feed reads. */
export function feedWarnings(counts: Record<string, number> | undefined, lastRow: Record<string, number> | undefined): string[] {
  if (!counts || !lastRow) return [];
  return Object.keys(lastRow).filter((k) => counts[k] !== undefined && counts[k] + 1 >= lastRow[k] * 0.9)
    .map((k) => `${k}: ${counts[k]} rows; the budget feed reads up to row ${lastRow[k]}.`);
}
