import type { GroceryList, Item, LatestPrice, ListLine, Op, Payment, PriceLine, Product, Receipt, ReceiptLine, Settings, Snapshot, Store } from './types';

/**
 * What the screens show: the last snapshot from the sheet with the unsent
 * saves laid on top, so a save is visible immediately (optimistic UI).
 */
export interface View {
  stores: Store[];
  items: Item[];
  itemById: Map<string, Item>;
  itemByBarcode: Map<string, Item>;
  categories: string[];
  units: string[];
  latest: LatestPrice[];
  openLines: PriceLine[];
  products: Product[];
  productById: Map<string, Product>;
  /** The sheet's script understands pack size and products (API v2+). */
  hasProducts: boolean;
  settings: Settings;
  /** Open lists (newest first) and their lines, with unsent changes applied. */
  lists: GroceryList[];
  listLines: ListLine[];
  /** Lists can be used: the script is API v3+ and the Lists/ListItems headers are as expected. */
  hasLists: boolean;
  /** Stores can be added and edited from the app (API v4+). */
  hasStoreEdit: boolean;
  /** Apps Script v6+: receipts save with no, some or too much payment (v5 refuses anything but exactly paid). */
  unpaidSaves: boolean;
  /** Why lists are off ('' when on). */
  listsNote: string;
  /** API v5: receipts with their lines and payments (unsent saves applied), and the Accounts tab. */
  receipts: Receipt[];
  receiptLines: ReceiptLine[];
  payments: Payment[];
  accounts: string[];
  hasReceipts: boolean;
  /** Why receipts are off ('' when on). */
  receiptsNote: string;
  rowCounts?: Record<string, number>;
  feedLastRow?: Record<string, number>;
}

export const DEFAULT_SETTINGS: Settings = { splitThreshold: 50, priceStaleDays: 60 };

export function emptyItem(id: string): Item {
  return { id, barcode: '', name: '', brand: '', category: '', unit: '', standardUnit: '', lastPrice: '', lastStoreId: '', lastPackSize: '', lastPromo: false, lastDate: '', packSize: '', productId: '' };
}

export function buildView(snap: Snapshot | null, ops: readonly Op[]): View {
  const items = new Map<string, Item>();
  (snap?.items ?? []).forEach((it) => items.set(it.id, { ...it, packSize: it.packSize ?? '', productId: it.productId ?? '' }));
  const products = new Map<string, Product>();
  (snap?.products ?? []).forEach((p) => products.set(p.id, { ...p }));
  const lines = new Map<string, PriceLine>();
  (snap?.openLines ?? []).forEach((l) => lines.set(l.id, { ...l }));
  const stores = new Map<string, Store>();
  (snap?.stores ?? []).forEach((s) => stores.set(s.id, { ...s }));
  const lists = new Map<string, GroceryList>();
  (snap?.lists?.lists ?? []).forEach((l) => lists.set(l.id, { ...l }));
  const listLines = new Map<string, ListLine>();
  (snap?.lists?.items ?? []).forEach((l) => listLines.set(l.id, { ...l }));
  const receipts = new Map<string, Receipt>();
  (snap?.receipts?.receipts ?? []).forEach((r) => receipts.set(r.id, { ...r }));
  const rLines = new Map<string, ReceiptLine>();
  (snap?.receipts?.lines ?? []).forEach((l) => rLines.set(l.id, { ...l }));
  const payments = new Map<string, Payment>();
  (snap?.receipts?.payments ?? []).forEach((p) => payments.set(p.id, { ...p }));
  /** A line that leaves a receipt stays as a price sighting (unlinked). */
  const unlink = (l: ReceiptLine) => { rLines.delete(l.id); const { receiptId: _r, qty: _q, bought: _b, ...rest } = l; lines.set(l.id, rest); };

  for (const op of ops) {
    if (op.type === 'item.upsert') {
      const cur = items.get(op.item.id) ?? emptyItem(op.item.id);
      const { product, ...fields } = op.item;
      const patch = Object.fromEntries(Object.entries(fields).filter(([, v]) => v !== undefined));
      items.set(op.item.id, { ...cur, ...patch });
      if (product && !products.has(product.id)) products.set(product.id, { ...product });
    } else if (op.type === 'price.upsert') {
      lines.set(op.line.id, { ...op.line });
      const it = items.get(op.line.itemId);
      if (it && (!it.lastDate || it.lastPrice === '' || it.lastDate <= op.line.date)) {
        items.set(it.id, { ...it, lastPrice: op.line.price, lastStoreId: op.line.storeId, lastPackSize: op.line.packSize, lastPromo: op.line.promo, lastDate: op.line.date });
      }
    } else if (op.type === 'price.delete') {
      lines.delete(op.id);
    } else if (op.type === 'store.upsert') {
      const cur = stores.get(op.store.id) ?? { id: op.store.id, name: '', defaultCategory: '' };
      stores.set(op.store.id, { ...cur, ...defined(op.store) });
    } else if (op.type === 'list.upsert') {
      const cur = lists.get(op.list.id) ?? { id: op.list.id, date: '', storeId: '', status: 'Open' as const };
      lists.set(op.list.id, { ...cur, ...defined(op.list) });
    } else if (op.type === 'listItem.upsert') {
      const cur = listLines.get(op.item.id) ?? { id: op.item.id, listId: '', itemId: '', qty: 1, buyAt: '', notes: '', keep: false };
      listLines.set(op.item.id, { ...cur, ...defined(op.item) });
    } else if (op.type === 'listItem.delete') {
      listLines.delete(op.id);
    } else if (op.type === 'receipt.save') {
      const r = op.receipt;
      const keep = new Set(r.lines.map((l) => l.id));
      const del = new Set(r.deleteLineIds ?? []);
      [...rLines.values()].filter((l) => l.receiptId === r.id && !keep.has(l.id)).forEach((l) => (del.has(l.id) ? rLines.delete(l.id) : unlink(l)));
      for (const l of r.lines) {
        const line: ReceiptLine = { id: l.id, date: r.date, itemId: l.itemId, storeId: r.storeId, price: l.price, packSize: l.packSize, packUnit: l.packUnit,
          promo: l.promo, notes: l.notes, barcode: l.barcode, receiptId: r.id, qty: l.qty, bought: true };
        rLines.set(l.id, line);
        lines.delete(l.id); // an unlinked line taken over by the receipt
        const it = items.get(l.itemId);
        if (it && (!it.lastDate || it.lastPrice === '' || it.lastDate <= r.date)) {
          items.set(it.id, { ...it, lastPrice: l.price, lastStoreId: r.storeId, lastPackSize: l.packSize, lastPromo: l.promo, lastDate: r.date });
        }
      }
      [...payments.values()].filter((p) => p.receiptId === r.id).forEach((p) => payments.delete(p.id));
      r.payments.forEach((p) => payments.set(p.id, { id: p.id, receiptId: r.id, account: p.account, amount: p.amount }));
      const paidC = r.payments.reduce((t, p) => t + Math.round(Number(p.amount) * 100), 0);
      receipts.set(r.id, { id: r.id, date: r.date, storeId: r.storeId, fallbackCategory: r.fallbackCategory, total: r.total,
        status: paidC === Math.round(Number(r.total) * 100) ? 'Closed' : 'Open',
        notes: r.notes, discount: r.discount, discountEntry: r.discountEntry, refreshedAt: receipts.get(r.id)?.refreshedAt });
    } else if (op.type === 'receipt.delete') {
      receipts.delete(op.id);
      [...payments.values()].filter((p) => p.receiptId === op.id).forEach((p) => payments.delete(p.id));
      [...rLines.values()].filter((l) => l.receiptId === op.id).forEach(unlink);
    }
  }
  const openLists = [...lists.values()].filter((l) => l.status !== 'Done')
    .sort((a, b) => b.date.localeCompare(a.date) || b.id.localeCompare(a.id));
  const openIds = new Set(openLists.map((l) => l.id));
  const apiVersion = snap?.apiVersion ?? 0;
  const listsNote = !snap ? 'Lists appear after the first sync.'
    : apiVersion < 3 ? 'Lists need the updated Apps Script (paste the new Code.gs, then Manage deployments › New version).'
    : snap.lists && !snap.lists.ok ? 'Lists are off: ' + (snap.lists.problem || 'the Lists/ListItems headers are not as expected.')
    : '';

  const receiptsNote = !snap ? 'Receipts appear after the first sync.'
    : apiVersion < 5 ? 'Receipts need the updated Apps Script (paste the new Code.gs, then Manage deployments › New version).'
    : snap.receipts && !snap.receipts.ok ? 'Receipts are off: ' + (snap.receipts.problem || 'the Receipts/ReceiptPayments headers are not as expected.')
    : '';
  const itemList = [...items.values()];
  const itemByBarcode = new Map<string, Item>();
  itemList.forEach((it) => { if (it.barcode) itemByBarcode.set(normalizeBarcode(it.barcode), it); });
  return {
    stores: [...stores.values()].sort((a, b) => a.name.localeCompare(b.name)),
    items: itemList,
    itemById: items,
    itemByBarcode,
    categories: snap?.categories ?? [],
    units: snap?.units ?? [],
    latest: snap?.latest ?? [],
    openLines: [...lines.values()],
    products: [...products.values()].sort((a, b) => a.name.localeCompare(b.name, undefined, { sensitivity: 'base' })),
    productById: products,
    hasProducts: apiVersion >= 2,
    settings: { ...DEFAULT_SETTINGS, ...(snap?.settings ?? {}) },
    lists: openLists,
    listLines: [...listLines.values()].filter((l) => openIds.has(l.listId)),
    hasLists: !listsNote,
    hasStoreEdit: apiVersion >= 4,
    unpaidSaves: apiVersion >= 6,
    listsNote,
    receipts: [...receipts.values()],
    receiptLines: [...rLines.values()],
    payments: [...payments.values()],
    accounts: snap?.receipts?.accounts ?? [],
    hasReceipts: !receiptsNote,
    receiptsNote,
    rowCounts: snap?.rowCounts,
    feedLastRow: snap?.feedLastRow,
  };
}

function defined<T extends object>(o: T): Partial<T> {
  return Object.fromEntries(Object.entries(o).filter(([, v]) => v !== undefined)) as Partial<T>;
}

/** Barcodes are compared as plain digit strings (the sheet may hold them as numbers or text). */
export function normalizeBarcode(raw: string): string {
  return String(raw).trim().replace(/^'/, '').replace(/\s+/g, '');
}

export function findByBarcode(view: View, raw: string): Item | undefined {
  const code = normalizeBarcode(raw);
  return view.itemByBarcode.get(code)
    // UPC-A (12 digits) is EAN-13 with a leading 0; scanners report either form.
    ?? (code.length === 12 ? view.itemByBarcode.get('0' + code) : undefined)
    ?? (code.length === 13 && code.startsWith('0') ? view.itemByBarcode.get(code.slice(1)) : undefined);
}

/**
 * A barcode typed on an item form: '' (none) is fine. Returns the cleaned barcode,
 * or an error message when it has odd characters or belongs to another item.
 */
export function checkBarcode(view: View, raw: string, exceptItemId?: string): { barcode: string } | { error: string } {
  const code = normalizeBarcode(raw);
  if (!code) return { barcode: '' };
  if (!/^[0-9A-Za-z-]{1,48}$/.test(code)) return { error: 'A barcode can only have digits, letters and dashes.' };
  const owner = findByBarcode(view, code);
  if (owner && owner.id !== exceptItemId) return { error: `That barcode already belongs to ${owner.name}.` };
  return { barcode: code };
}

/** 1–5 digits can't be a product barcode (EAN-8 is the shortest); typed by mistake or as a dummy. */
export function tooShortForBarcode(raw: string): boolean { return /^\d{1,5}$/.test(normalizeBarcode(raw)); }

/** Typed text that should be looked up as a barcode: 6+ digits that no item has. */
export function looksLikeNewBarcode(view: View, text: string): boolean { const c = normalizeBarcode(text); return /^\d{6,}$/.test(c) && !findByBarcode(view, c); }

/** "500 g" style pack size of an item, or ''. */
export function itemSize(it: Item): string {
  return it.packSize !== '' && it.packSize !== undefined ? `${it.packSize} ${it.unit}`.trim() : '';
}

/** The unlinked line for this item at this store on this date, if any (rescan edits it). */
export function findOpenLine(view: View, itemId: string, storeId: string, date: string): PriceLine | undefined {
  return view.openLines.find((l) => l.itemId === itemId && l.storeId === storeId && l.date === date);
}

/** Same name + brand (ignoring case and spacing): likely the same product. */
export function findLikelyDuplicate(view: View, name: string, brand: string, exceptId?: string): Item | undefined {
  const norm = (s: string) => s.toLowerCase().replace(/[^a-z0-9]+/g, ' ').trim();
  const n = norm(name), b = norm(brand);
  if (!n) return undefined;
  return view.items.find((it) => it.id !== exceptId && norm(it.name) === n && norm(it.brand) === b);
}

export function priceHere(view: View, itemId: string, storeId: string): LatestPrice | undefined {
  return view.latest.find((l) => l.itemId === itemId && l.storeId === storeId);
}

export function cheapest(view: View, itemId: string): LatestPrice | undefined {
  return view.latest.find((l) => l.itemId === itemId && l.cheapest);
}
