/**
 * Client-made IDs in the sheet's existing style: a prefix plus 8 lowercase hex
 * digits (e.g. I1a2b3c4d, Pe554e163). Made on the phone so a save can be shown
 * and retried before the server ever sees it.
 */
export type IdPrefix = 'S' | 'I' | 'P' | 'R' | 'PM' | 'PR' | 'L' | 'LI' | 'op';

export function randomHex8(rand: (buf: Uint8Array) => Uint8Array = (b) => crypto.getRandomValues(b)): string {
  const buf = rand(new Uint8Array(4));
  return Array.from(buf, (b) => b.toString(16).padStart(2, '0')).join('');
}

export function newId(prefix: IdPrefix, taken?: { has(id: string): boolean }, rand?: (buf: Uint8Array) => Uint8Array): string {
  for (let i = 0; i < 20; i++) {
    const id = prefix + randomHex8(rand);
    if (!taken || !taken.has(id)) return id;
  }
  throw new Error('Could not make a unique ID');
}

export const ID_PATTERNS = {
  item: /^I[0-9a-f]{8}$/,
  receipt: /^R[0-9a-f]{8}$/,
  payment: /^PM[0-9a-f]{8}$/,
  price: /^P[0-9a-f]{8}$/,
  product: /^PR[0-9a-f]{8}$/,
  store: /^S[0-9a-f]{8}$/,
  list: /^L[0-9a-f]{8}$/,
  listItem: /^LI[0-9a-f]{8}$/,
};

/** Anonymous contributor ID: "C" + 32 lowercase hex (128 random bits), made once per sheet by the Apps Script. */
export const CONTRIBUTOR_ID_PATTERN = /^C[0-9a-f]{32}$/;
export function isContributorId(id: unknown): id is string {
  return typeof id === 'string' && CONTRIBUTOR_ID_PATTERN.test(id);
}
