/**
 * Stores tab: pick-or-type choices, the add/edit form's checks, and the
 * store.upsert change (API v4). IDs are made on the device ("S" + 8 hex) so a
 * new store can be used at once, offline, and retries never duplicate it.
 */
import type { Op, Store } from './types';
import type { View } from './model';
import { newId } from './ids';
import { cleanText, distinctChoices } from './choices';

export interface StoreFields { name: string; branchArea: string; chain: string; transpo: number | ''; defaultCategory: string; notes: string }

const norm = (s: string | undefined) => cleanText(s).toLocaleLowerCase().replace(/[^\p{L}\p{N}]+/gu, '');

/** Store names for the picker, A–Z. */
export function storeNames(stores: readonly Store[]): string[] {
  return [...stores].map((s) => s.name).filter(Boolean).sort((a, b) => a.localeCompare(b, undefined, { sensitivity: 'base' }));
}

/** The store a typed name means (ignoring case, spaces and punctuation), if any. */
export function storeByName(stores: readonly Store[], typed: string): Store | undefined {
  const k = norm(typed);
  return k ? stores.find((s) => norm(s.name) === k) : undefined;
}

/** Second line under a store in the picker: "SM East · SM Supermarket". */
export function storeHint(s: Store | undefined): string {
  return s ? [s.branchArea, s.chain && s.chain !== s.name ? s.chain : ''].filter(Boolean).join(' · ') : '';
}

export const areaChoices = (stores: readonly Store[]) => distinctChoices(stores.map((s) => s.branchArea || ''));
export const chainChoices = (stores: readonly Store[]) => distinctChoices(stores.map((s) => s.chain || ''));

/** "60", "₱60", "" -> 60 / '' ; null when not a number of pesos (0 or more). */
export function parseTravel(raw: string): number | '' | null {
  const s = raw.trim().replace(/^₱/, '').replace(/,/g, '').trim();
  if (!s) return '';
  if (!/^\d+(\.\d{1,2})?$/.test(s)) return null;
  return Number(s);
}

/** A store that is probably the same one: same name (ignoring case/spaces/punctuation), or same chain and same area. */
export function findDuplicateStore(stores: readonly Store[], f: Pick<StoreFields, 'name' | 'chain' | 'branchArea'>, exceptId?: string): Store | undefined {
  const others = stores.filter((s) => s.id !== exceptId);
  const byName = others.find((s) => norm(s.name) === norm(f.name));
  if (byName) return byName;
  if (norm(f.chain) && norm(f.branchArea)) return others.find((s) => norm(s.chain) === norm(f.chain) && norm(s.branchArea) === norm(f.branchArea));
  return undefined;
}

export function checkStoreFields(f: StoreFields): string {
  if (!cleanText(f.name)) return 'Type a store name.';
  if (cleanText(f.name).length > 100) return 'Store name is too long.';
  return '';
}

/** New store (no `existing`) or an edit of `existing` (only changed fields are sent). */
export function planStoreSave(view: View, f: StoreFields, existing?: Store): { store: Store; op: Op } {
  const clean = { name: cleanText(f.name), branchArea: cleanText(f.branchArea), chain: cleanText(f.chain), transpo: f.transpo, defaultCategory: cleanText(f.defaultCategory), notes: f.notes.trim() };
  if (!existing) {
    const id = newId('S', new Set(view.stores.map((s) => s.id)));
    const store: Store = { id, ...clean };
    return { store, op: { opId: newId('op'), type: 'store.upsert', store } };
  }
  const change: Partial<Store> & { id: string } = { id: existing.id };
  (Object.keys(clean) as (keyof typeof clean)[]).forEach((k) => {
    const before = existing[k] ?? '';
    if (String(before) !== String(clean[k])) (change as Record<string, unknown>)[k] = clean[k];
  });
  return { store: { ...existing, ...clean }, op: { opId: newId('op'), type: 'store.upsert', store: change } };
}
