import { newId } from './ids';
import { findOpenLine, type View } from './model';
import type { Item, ItemFields, Op } from './types';

/**
 * A scan session lives on the device only (no sheet row).
 * Mode "items": scans add or confirm Items; never writes Prices.
 * Mode "store": scans at one store on one date; a typed price adds or edits
 * that day's unlinked Prices line, a blank price writes no line.
 */
export type ScanMode = 'items' | 'store' | 'list' | 'receipt';

export interface ScanSession {
  mode: ScanMode;
  storeId: string;   // '' in items mode
  date: string;      // yyyy-mm-dd; '' in items mode
  startedAt: number;
  /** Price lines this session created, so clearing a price can remove its own line. */
  createdLineIds: string[];
  recent: { barcode: string; itemId: string; label: string; at: number }[];
  /** List mode: the list that scanned items are added to. */
  listId?: string;
}

export function startSession(mode: ScanMode, storeId: string, date: string, now = Date.now()): ScanSession {
  if (mode === 'store' && (!storeId || !/^\d{4}-\d{2}-\d{2}$/.test(date))) throw new Error('Pick a store and a date.');
  return { mode, storeId: mode === 'store' ? storeId : '', date: mode === 'store' ? date : '', startedAt: now, createdLineIds: [], recent: [] };
}

/** Parses what was typed in a price box. '' means "no price"; anything else must be a number > 0. */
export function parsePrice(raw: string): number | '' | null {
  const s = raw.trim().replace(/,/g, '');
  if (!s) return '';
  if (!/^\d+(\.\d{1,2})?$/.test(s)) return null;
  const n = Number(s);
  return n > 0 ? n : n === 0 ? '' : null;
}

export function parsePackSize(raw: string): number | '' | null {
  const s = raw.trim().replace(/,/g, '');
  if (!s) return '';
  if (!/^\d+(\.\d+)?$/.test(s)) return null;
  return Number(s);
}

export interface PriceInput { price: number | ''; packSize: number | ''; packUnit: string; promo: boolean; notes?: string }

export interface SavePlan { ops: Op[]; message: string; lineId?: string }

const opId = () => newId('op');

/** What saving the price card for a known item writes. */
export function planPriceSave(view: View, session: ScanSession, item: Item, barcode: string, input: PriceInput): SavePlan {
  if (session.mode !== 'store') return { ops: [], message: `${item.name}: already in Items.` };
  const existing = findOpenLine(view, item.id, session.storeId, session.date);
  if (input.price === '') {
    if (existing && session.createdLineIds.includes(existing.id)) {
      return { ops: [{ opId: opId(), type: 'price.delete', id: existing.id }], message: `${item.name}: price removed.` };
    }
    if (existing) return { ops: [], message: `${item.name}: kept the price saved earlier today (${existing.price}).` };
    return { ops: [], message: `${item.name}: no price, nothing saved.` };
  }
  const lineId = existing?.id ?? newId('P', { has: (id) => view.openLines.some((l) => l.id === id) });
  return {
    lineId,
    message: `${item.name}: ${existing ? 'price updated' : 'price saved'}.`,
    ops: [{
      opId: opId(), type: 'price.upsert',
      line: {
        id: lineId, date: session.date, itemId: item.id, storeId: session.storeId, price: input.price,
        packSize: input.packSize, packUnit: input.packUnit, promo: input.promo, notes: input.notes ?? (existing?.notes || ''),
        barcode: barcode || item.barcode,
      },
    }],
  };
}

/** What saving the new-item form writes: the item, plus a price line in store mode when a price was typed. */
export function planNewItem(view: View, session: ScanSession, fields: Omit<ItemFields, 'id'>, input: PriceInput | null): SavePlan & { itemId: string } {
  const itemId = newId('I', view.itemById);
  const item: Item = {
    id: itemId, barcode: fields.barcode ?? '', name: fields.name ?? '', brand: fields.brand ?? '', category: fields.category ?? '',
    unit: fields.unit ?? '', standardUnit: fields.standardUnit ?? '', lastPrice: '', lastStoreId: '', lastPackSize: '', lastPromo: false, lastDate: '',
    packSize: fields.packSize ?? '', productId: fields.productId ?? '',
  };
  const ops: Op[] = [{ opId: opId(), type: 'item.upsert', item: { id: itemId, ...fields } }];
  let message = `${item.name}: added to Items.`;
  let lineId: string | undefined;
  if (session.mode === 'store' && input && input.price !== '') {
    const p = planPriceSave(view, session, item, item.barcode, input);
    ops.push(...p.ops);
    lineId = p.lineId;
    message = `${item.name}: added with price.`;
  }
  return { itemId, ops, message, lineId };
}

/** Link a scanned barcode to an existing item that has none (the "same item" answer on the duplicate warning). */
export function planLinkBarcode(item: Item, barcode: string): Op {
  return { opId: opId(), type: 'item.upsert', item: { id: item.id, barcode } };
}
