/**
 * Price comparison for the Plan and Lists screens, worked out on the phone
 * from the snapshot (works offline, updates instantly, no extra script runs).
 *
 * Rules:
 * - Items in a Product (same standard unit, with a pack size) are compared by
 *   price per standard unit (kg / L / pc); other items only with themselves
 *   across stores (per unit when every price has one, else per pack).
 * - Age: fresh <= 30 days, ageing up to Settings PriceStaleDays (60), then old.
 *   Old prices and promos older than 14 days are not used for "cheaper at"
 *   badges (a promo that may have ended falls back to the newest regular price).
 */
import type { Item, LatestPrice, Store } from './types';
import type { View } from './model';

export const FRESH_DAYS = 30;
export const PROMO_DAYS = 14;

export function unitFactor(unit: string): number {
  const u = String(unit || '').trim().toLowerCase();
  return u === 'g' || u === 'ml' ? 0.001 : u === 'doz' ? 12 : 1;
}

/** The item's pack size in standard units (500 g -> 0.5), or null when unknown. */
export function stdQty(item: Item): number | null {
  const n = Number(item.packSize);
  return item.packSize !== '' && n > 0 ? n * unitFactor(item.unit) : null;
}

export function daysBetween(from: string, to: string): number {
  const p = (s: string) => { const [y, m, d] = s.split('-').map(Number); return Date.UTC(y, (m || 1) - 1, d || 1); };
  if (!/^\d{4}-\d{2}-\d{2}/.test(from) || !/^\d{4}-\d{2}-\d{2}/.test(to)) return Infinity;
  return Math.round((p(to.slice(0, 10)) - p(from.slice(0, 10))) / 86400000);
}

export type Age = 'fresh' | 'ageing' | 'old';
export function ageOf(days: number, staleDays: number): Age {
  if (!(days <= staleDays)) return 'old';
  return days > Math.min(FRESH_DAYS, staleDays) ? 'ageing' : 'fresh';
}

export interface PricePoint {
  itemId: string; storeId: string;
  /** Pack price. */
  price: number;
  /** Price per standard unit, or null when the pack size is unknown. */
  perStd: number | null;
  date: string; days: number; age: Age;
  promo: boolean;
  /** A promo older than 14 days. */
  promoEnded: boolean;
  /** The date is only approximate (seed data). */
  approx: boolean;
  /** This is the newest regular price, used because the newer promo may have ended. */
  regular: boolean;
}

function perStdOf(price: number, given: number | '' | undefined, item: Item | undefined): number | null {
  if (typeof given === 'number' && given > 0) return given;
  const q = item ? stdQty(item) : null;
  return q ? Math.round((price / q) * 100) / 100 : null;
}

/** What the screens show for a LatestPrices row (null when it has no price). */
export function displayPoint(lp: LatestPrice, item: Item | undefined, today: string, staleDays: number): PricePoint | null {
  if (typeof lp.price !== 'number' || !(lp.price > 0)) return null;
  const days = daysBetween(lp.date, today);
  const promo = !!lp.promo;
  return {
    itemId: lp.itemId, storeId: lp.storeId, price: lp.price, perStd: perStdOf(lp.price, lp.perStdUnit, item),
    date: lp.date, days, age: ageOf(days, staleDays), promo, promoEnded: promo && days > PROMO_DAYS,
    approx: !!lp.approxDate, regular: false,
  };
}

/** The price to use for "cheaper at" badges, or null when it should not be used (old, or a promo that may have ended). */
export function badgePoint(lp: LatestPrice, item: Item | undefined, today: string, staleDays: number): PricePoint | null {
  const d = displayPoint(lp, item, today, staleDays);
  if (!d) return null;
  if (d.promoEnded) {
    if (typeof lp.regularPrice !== 'number' || !(lp.regularPrice > 0) || !lp.regularDate) return null;
    const days = daysBetween(lp.regularDate, today);
    if (ageOf(days, staleDays) === 'old') return null;
    return { ...d, price: lp.regularPrice, perStd: perStdOf(lp.regularPrice, lp.regularPerStdUnit, item), date: lp.regularDate,
      days, age: ageOf(days, staleDays), promo: false, promoEnded: false, approx: false, regular: true };
  }
  return d.age === 'old' ? null : d;
}

export interface Group {
  key: string;
  /** Product name, or the item name. */
  name: string;
  /** Standard unit label for per-unit prices (kg, L, pc, …). */
  unit: string;
  productId: string;
  /** Compared per standard unit (always for products). */
  isProduct: boolean;
  itemIds: string[];
}

const same = (a: string, b: string) => a.trim().toLowerCase() === b.trim().toLowerCase();

/** The comparison group of an item: its Product when it qualifies (same standard unit, pack size known), else the item alone. */
export function groupOf(view: View, item: Item): Group {
  const p = item.productId ? view.productById.get(item.productId) : undefined;
  if (p) {
    const std = p.standardUnit || item.standardUnit;
    const fits = (it: Item) => it.productId === p.id && same(it.standardUnit || '', std) && stdQty(it) !== null;
    if (fits(item)) {
      return { key: 'P:' + p.id, name: p.name, unit: std, productId: p.id, isProduct: true, itemIds: view.items.filter(fits).map((i) => i.id) };
    }
  }
  return { key: 'I:' + item.id, name: item.name, unit: item.standardUnit || item.unit, productId: '', isProduct: false, itemIds: [item.id] };
}

export interface Pools {
  groups: Map<string, Group>;
  groupOfItem: Map<string, Group>;
  /** Shown prices, per group. */
  display: Map<string, PricePoint[]>;
  /** Prices usable for badges, per group. */
  badge: Map<string, PricePoint[]>;
}

export function buildPools(view: View, today: string): Pools {
  const stale = view.settings.priceStaleDays;
  const groups = new Map<string, Group>(), groupOfItem = new Map<string, Group>();
  const display = new Map<string, PricePoint[]>(), badge = new Map<string, PricePoint[]>();
  for (const it of view.items) {
    const g = groupOf(view, it);
    groupOfItem.set(it.id, groups.get(g.key) ?? g);
    if (!groups.has(g.key)) groups.set(g.key, g);
  }
  for (const lp of view.latest) {
    const it = view.itemById.get(lp.itemId);
    const g = it && groupOfItem.get(it.id);
    if (!it || !g) continue;
    const d = displayPoint(lp, it, today, stale);
    const b = badgePoint(lp, it, today, stale);
    if (g.isProduct && d && d.perStd === null) continue; // can't compare within the product
    if (d) push(display, g.key, d);
    if (b && !(g.isProduct && b.perStd === null)) push(badge, g.key, b);
  }
  return { groups, groupOfItem, display, badge };
}

function push<K, V>(m: Map<K, V[]>, k: K, v: V) { const a = m.get(k); if (a) a.push(v); else m.set(k, [v]); }

/** Compare per standard unit when the group is a product, or when every price given has a per-unit value. */
export function usesPerUnit(g: Group, pts: readonly PricePoint[]): boolean {
  return g.isProduct || (pts.length > 0 && pts.every((p) => p.perStd !== null));
}
export function metric(p: PricePoint, perUnit: boolean): number { return perUnit ? (p.perStd as number) : p.price; }

export function minBy(pts: readonly PricePoint[], perUnit: boolean): PricePoint | undefined {
  let best: PricePoint | undefined;
  for (const p of pts) if (!best || metric(p, perUnit) < metric(best, perUnit) - 1e-9) best = p;
  return best;
}

/** ₱ difference for one pack like `here`, given a per-unit (or per-pack) difference. */
export function packSaving(here: PricePoint, diff: number, perUnit: boolean): number {
  if (!perUnit) return round2(diff);
  return round2(diff * (here.price / (here.perStd as number)));
}
export const round2 = (n: number) => Math.round(n * 100) / 100;

/* ---------------------------------------------------------------- Plan screen */

export type PlanSection = 'cheapest' | 'elsewhere' | 'only';
export interface PlanRow {
  group: Group;
  section: PlanSection;
  /** Best price at the chosen store(s). */
  here: PricePoint;
  /** Best usable price at any other store. */
  other?: PricePoint;
  perUnit: boolean;
  /** How much more (cheapest) or less (elsewhere) the other store is, per unit (or per pack). */
  diff: number;
  /** The same in ₱ for the pack sold here. */
  packDiff: number;
}

/** Trip areas: stores grouped by Stores BranchArea; a store with no area is its own trip. */
export function areaOf(store: Store | undefined, storeId: string): string {
  return (store?.branchArea || '').trim() || storeId;
}

export interface Where { key: string; label: string; storeIds: string[]; isArea: boolean }

/** Choices for the Plan screen: trip areas with 2+ stores first, then every store. */
export function whereChoices(stores: readonly Store[]): Where[] {
  const byArea = new Map<string, Store[]>();
  stores.forEach((s) => { const a = (s.branchArea || '').trim(); if (a) push(byArea, a, s); });
  const areas = [...byArea.entries()].filter(([, ss]) => ss.length > 1)
    .sort((a, b) => a[0].localeCompare(b[0]))
    .map(([a, ss]) => ({ key: 'A:' + a, label: `${a} (${ss.length} stores)`, storeIds: ss.map((s) => s.id), isArea: true }));
  const singles = [...stores].sort((a, b) => a.name.localeCompare(b.name)).map((s) => ({ key: 'S:' + s.id, label: s.name, storeIds: [s.id], isArea: false }));
  return [...areas, ...singles];
}

export function planFor(view: View, storeIds: readonly string[], today: string, pools = buildPools(view, today)): PlanRow[] {
  const inSet = new Set(storeIds);
  const rows: PlanRow[] = [];
  for (const [key, shown] of pools.display) {
    const g = pools.groups.get(key)!;
    const hereShown = shown.filter((p) => inSet.has(p.storeId));
    if (!hereShown.length) continue;
    const usable = pools.badge.get(key) ?? [];
    const hereUsable = usable.filter((p) => inSet.has(p.storeId));
    const others = usable.filter((p) => !inSet.has(p.storeId));
    const perUnit = usesPerUnit(g, [...hereShown, ...hereUsable, ...others]);
    const here = minBy(hereUsable.length ? hereUsable : hereShown, perUnit)!;
    const other = minBy(others, perUnit);
    if (!other) { rows.push({ group: g, section: 'only', here, perUnit, diff: 0, packDiff: 0 }); continue; }
    const d = metric(other, perUnit) - metric(here, perUnit);
    const section: PlanSection = d >= 0 ? 'cheapest' : 'elsewhere';
    const diff = round2(Math.abs(d));
    rows.push({ group: g, section, here, other, perUnit, diff, packDiff: packSaving(here, Math.abs(d), perUnit) });
  }
  const order: Record<PlanSection, number> = { cheapest: 0, elsewhere: 1, only: 2 };
  return rows.sort((a, b) => order[a.section] - order[b.section]
    || (a.section === 'only' ? a.group.name.localeCompare(b.group.name) : b.packDiff - a.packDiff || a.group.name.localeCompare(b.group.name)));
}

/* ---------------------------------------------------------------- same product (Lists and the price card) */

export interface SameProduct {
  group: Group;
  /** This item's cheapest store (per unit). */
  store?: PricePoint;
  /** The cheapest other brand in the same pack size. */
  sameSize?: PricePoint;
  /** The cheapest of any pack or brand in the product, per standard unit (may be this item). */
  anySize?: PricePoint;
}

const brandKey = (it: Item | undefined) => (it?.brand || '').trim().toLowerCase();

/**
 * For an item in a Product: its cheapest store, the cheapest other brand of the same size and
 * the cheapest of any size, all per standard unit. Uses the "cheaper at" prices (no old prices,
 * a promo older than 14 days falls back to the newest regular price). Null when the item is not
 * in a Product or nothing is priced.
 */
export function sameProduct(view: View, itemId: string, today: string, pools = buildPools(view, today)): SameProduct | null {
  const item = view.itemById.get(itemId);
  const g = item ? pools.groupOfItem.get(item.id) : undefined;
  if (!item || !g || !g.isProduct) return null;
  const pts = pools.badge.get(g.key) ?? [];
  const size = stdQty(item);
  const mine = brandKey(item);
  const sameSizeOther = (p: PricePoint) => {
    if (p.itemId === item.id) return false;
    const o = view.itemById.get(p.itemId);
    const q = o ? stdQty(o) : null;
    if (q === null || size === null || Math.abs(q - size) > 1e-9) return false;
    return !mine || brandKey(o) !== mine;              // another brand (or a brand-less twin)
  };
  const out: SameProduct = {
    group: g,
    store: minBy(pts.filter((p) => p.itemId === item.id), true),
    sameSize: minBy(pts.filter(sameSizeOther), true),
    anySize: minBy(pts, true),
  };
  return out.store || out.sameSize || out.anySize ? out : null;
}
