/**
 * Pure camera helpers (unit-tested): which part of the frame to decode,
 * mapping results back, which camera tweaks to ask for, and the
 * diagnostics line shown under "This device".
 */
import type { Point } from './scanFeedback';

export interface Crop { x: number; y: number; width: number; height: number; scale: number }

/**
 * The centred band of the frame to decode: `fracW` × `fracH` of the part the
 * user actually sees (the camera box crops the frame with object-fit: cover),
 * drawn at most `maxWidth` pixels wide (scale ≤ 1).
 */
export function centerCrop(
  video: { width: number; height: number },
  view: { width: number; height: number },
  fracW = 0.6, fracH = 0.4, maxWidth = 640,
): Crop | null {
  if (!video.width || !video.height) return null;
  // Visible part of the frame under object-fit: cover (whole frame if the box has no size yet).
  let visW = video.width, visH = video.height;
  if (view.width > 0 && view.height > 0) {
    const scale = Math.max(view.width / video.width, view.height / video.height);
    visW = Math.min(video.width, view.width / scale);
    visH = Math.min(video.height, view.height / scale);
  }
  const width = Math.round(visW * fracW);
  const height = Math.round(visH * fracH);
  const x = Math.round((video.width - width) / 2);
  const y = Math.round((video.height - height) / 2);
  return { x, y, width, height, scale: Math.min(1, maxWidth / width) };
}

/** Points found in the (scaled) crop → points in the full video frame. */
export function uncrop(points: readonly Point[], crop: Crop): Point[] {
  return points.map((p) => ({ x: crop.x + p.x / crop.scale, y: crop.y + p.y / crop.scale }));
}

/** The subset of MediaTrackCapabilities we look at (Chrome on Android exposes these). */
export interface CameraCaps {
  focusMode?: string[];
  zoom?: { min: number; max: number; step?: number };
  torch?: boolean;
}

/**
 * Constraints to apply after the camera starts: continuous autofocus when the
 * camera offers it, and a modest zoom so the phone can be held further back,
 * where it focuses (close-up barcodes are often blurry).
 */
export function cameraTweaks(caps: CameraCaps | null | undefined, wantZoom = 1.6): { focusMode?: string; zoom?: number } {
  const out: { focusMode?: string; zoom?: number } = {};
  if (caps?.focusMode?.includes('continuous')) out.focusMode = 'continuous';
  const z = caps?.zoom;
  if (z && Number.isFinite(z.min) && Number.isFinite(z.max) && z.max > 1) {
    let v = Math.min(Math.max(wantZoom, z.min), z.max);
    if (z.step && z.step > 0) v = z.min + Math.round((v - z.min) / z.step) * z.step;
    out.zoom = Math.round(v * 100) / 100;
  }
  return out;
}

export interface ScannerInfo {
  engine: 'native' | 'zxing';
  /** Why ZXing was used, when it was. */
  reason?: string;
  width?: number;
  height?: number;
  focusMode?: string;
  zoom?: number;
  torch?: boolean;
  /** Average time one detect() call took, and how many ran. */
  avgDetectMs?: number;
  detects?: number;
  at: number;
}

export function describeScanner(i: ScannerInfo | null | undefined): string {
  if (!i) return 'Scanner: not used yet on this device.';
  const parts = [
    i.engine === 'native' ? 'Scanner: built-in (native)' : `Scanner: ZXing (wasm)${i.reason ? ' — ' + i.reason : ''}`,
    i.width && i.height ? `camera ${i.width}×${i.height}` : 'camera size unknown',
    `focus ${i.focusMode || 'unknown'}`,
    i.zoom ? `zoom ${i.zoom}×` : '',
    i.torch ? 'flashlight available' : '',
    i.detects ? `${i.avgDetectMs ?? '?'} ms per try (${i.detects} tries)` : '',
  ];
  return parts.filter(Boolean).join(' · ');
}

/** Running average that doesn't keep every sample. */
export class DetectStats {
  count = 0;
  private total = 0;
  add(ms: number) { this.count++; this.total += ms; }
  get avg() { return this.count ? Math.round(this.total / this.count) : 0; }
}
